insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْعِلْمُ ثَلاثَةٌ، وَمَا سِوَى ذَلِكَ فَهُوَ فَضْلٌ: آيَةٌ مُحْكَمَةٌ، أَوْ سُنَّةٌ قَائِمَةٌ، أَوْ فَرِيضَةٌ عَادِلَةٌ". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "വിജ്ഞാനങ്ങൾ മൂന്നെണ്ണമാണ്. അവയൊഴിച്ചുള്ളതൊക്കെ ആവശ്യരഹിതമാണ്. യുക്തിസമ്പുഷ്ടമായ ദൈവവചനം, സുസ്ഥിരമായ തിരുചര്യ, ദൈവഹിതമനുസരിച്ച അനന്തരാവകാശ ഓഹരി എന്നിവയാണവ." (ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 603, 603, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَعَلَّمُوا الْقُرْآنَ وَالْفَرَائِضَ، وَعَلِّمُوا النَّاسَ، فَإِنِّي مَقْبُوضٌ". (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഖുർആനും അനന്തരാവകാശ നിയമങ്ങളും നിങ്ങൾ പഠിക്കുകയും ജനങ്ങളെ പഠിപ്പിക്കുകയും ചെയ്യുക. ഞാൻ മരണം കാത്തുകഴിയുകയാണ്." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 603, 603, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا أَبَا هُرَيْرَةَ، تَعَلَّمُوا الْفَرَائِضَ وَعَلِّمُوهَا، فَإِنَّهُ نِصْفُ الْعِلْمِ، وَهُوَ يُنْسَى، وَهُوَ أَوَّلُ شَيْءٍ يُنْزَعُ مِنْ أُمَّتِي". فِي سَنَدِهِ ضَعِيفٌ. (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അബൂഹുറൈറാ, ഫറാഇള് നിങ്ങൾ പഠിക്കുകയും പഠിപ്പിക്കുകയും ചെയ്യുക. വിജ്ഞാനത്തിന്റെ പാതിയാണത്. അതിനെ പെട്ടെന്ന് മറന്നുകളയുകയും ചെയ്യും. ആദ്യമായി എന്റെ സമുദായത്തിൽ നിന്നും ഉന്മൂലനം ചെയ്യപ്പെടുന്നതും അതായിരിക്കും." പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 603, 603, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُؤْتَى بِالرَّجُلِ الْمَيِّتِ عَلَيْهِ الدَّيْنُ، فَيَسْأَلُ: "هَلْ تَرَكَ لِدَيْنِهِ مِنْ قَضَاءٍ". فَإِنْ حُدِّثَ أَنَّهُ تَرَكَ وَفَاءً صَلَّى عَلَيْهِ، وَإِلَّا قَالَ: "صَلُّوا عَلَى صَاحِبِكُمْ". فَلَمَّا فَتَحَ اللَّهُ عَلَيْهِ الْفُتُوحَ قَالَ: "أَنَا أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ، فَمَنْ تُوُفِّيَ وَعَلَيْهِ دَيْنٌ فَعَلَيَّ قَضَاؤُهُ، وَمَنْ تَرَكَ مَالاً فَهُوَ لِوَرَثَتِهِ". (م)', 'അബൂഹുറൈറ(റ): കടബാധിതനായ പരേതനെ തിരുസന്നിധിയിൽ കൊണ്ടുവന്നാൽ അവിടുന്ന് ചോദിക്കും: "കടം കൊടുത്തുവീട്ടാൻ അദ്ദേഹം വല്ലതും ബാക്കിവെച്ചിട്ടുണ്ടോ?" വീട്ടാനുള്ള സ്വത്ത് ഉപേക്ഷിച്ചിട്ടുണ്ടെന്ന് പറഞ്ഞാൽ തിരുമേനി(സ) അയാൾക്ക്വേണ്ടി നിസ്കരിക്കും. ഇല്ലെങ്കിൽ അവിടുന്ന് പറയും: "നിങ്ങളുടെ കൂട്ടുകാരനു വേണ്ടി നിങ്ങൾ നിസ്കരിക്കുക." കാലക്രമേണ വിജയങ്ങളോരോന്നായി അല്ലാഹു സമ്മാനിച്ചപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "സത്യവിശ്വാസികളോട് അവരേക്കാൾ ഞാൻ ബന്ധപ്പെട്ടിരിക്കുന്നു. കടബാധ്യതയുണ്ടായിരിക്കെ ഒരാൾ മരണപ്പെട്ടാൽ അത് വീട്ടേണ്ട ബാധ്യത എനിക്കാണ്. വല്ലവനും സ്വത്ത് ഉപേക്ഷിച്ചുവെച്ചിട്ടുണ്ടെങ്കിൽ അവന്റെ അനന്തരാവകാശികൾക്കാണത്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 603, 604, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَرَكَ مَالاً فَلِأَهْلِهِ، وَمَنْ تَرَكَ ضَيَاعًا فَإِلَيَّ". حَسَنٌ صَحِيحٌ. (ق,د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരുവൻ സമ്പത്ത് ബാക്കിവെച്ചിട്ടുണ്ടെങ്കിൽ അത് ബന്ധുക്കൾക്ക് അവകാശപ്പെട്ടതാണ്. ഒരുവൻ ആശ്രിതരെ ഇട്ടേച്ചുപോയാൽ അവരുടെ ആശ്രയസ്ഥാനം ഞാനാണ്." (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 604, 604, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ هُزَيْلِ بْنِ شُرَحْبِيلَ الْأَوْدِيِّ قَالَ: جَاءَ رَجُلٌ إِلَى أَبِي مُوسَى الْأَشْعَرِيِّ وَسَلْمَانَ بْنِ رَبِيعَةَ، فَسَأَلَهُمَا عَنِ ابْنَةٍ وَابْنَةِ ابْنٍ وَأُخْتٍ لِأَبٍ وَأُمٍّ، فَقَالا: لِابْنَتِهِ النِّصْفُ، وَلِلْأُخْتِ مِنَ الْأَبِ وَالْأُمِّ النِّصْفُ، وَلَمْ يُوَرِّثَا ابْنَةَ الِابْنِ شَيْئًا. وَأْتِ ابْنَ مَسْعُودٍ فَإِنَّهُ سَيُتَابِعُنَا. فَأَتَاهُ الرَّجُلُ فَسَأَلَهُ وَأَخْبَرَهُ بِقَوْلِهِمَا، فَقَالَ: لَقَدْ ضَلَلْتُ إِذًا وَمَا أَنَا مِنَ الْمُهْتَدِينَ، وَلَكِنِّي سَأَقْضِي فِيهَا بِقَضَاءِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لِابْنَتِهِ النِّصْفُ، وَلِابْنَةِ الِابْنِ سَهْمٌ تَكْمِلَةُ الثُّلُثَيْنِ، وَمَا بَقِيَ فَلِلْأُخْتِ مِنَ الْأَبِ وَالْأُمِّ. (خ,د,ت,ن,جه)', 'ഹുസൈലുബ്നു ശുറഹ്ബീലിൽ ഔദീ(റ): അബൂമൂസൽ അശ്അരി(റ), സൽമാനുബ്നു റബീഅ(റ) എന്നിവരെ സമീപിച്ച്, മകളുടെയും മകന്റെ മകളുടെയും പിതാവും മാതാവും ഒത്ത സഹോദരിയുടെയും അനന്തരാവകാശത്തെക്കുറിച്ച് ഒരാൾ ചോദിച്ചു. അവർ പറഞ്ഞു: മകൾക്ക് പകുതി, പിതാവും മാതാവുമൊത്ത സഹോദരിക്ക് പകുതി. അവർ മകന്റെ മകൾക്ക് അനന്തരാവകാശം നിശ്ചയിച്ചില്ല. (ശേഷം പറഞ്ഞു:) നീ ഇബ്നുമസ്ഊദ്(റ)വിന്റെ സന്നിധിയിൽ ചെല്ലൂ. അദ്ദേഹവും ഇപ്രകാരമായിരിക്കും പറയുക. ഉടനെ അയാൾ അദ്ദേഹത്തെ സമീപിച്ച് വിഷയം ചോദിക്കുകയും അവർ പറഞ്ഞത് വിശദീകരിച്ചുകൊടുക്കുകയും ചെയ്തു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അങ്ങനെയെങ്കിൽ ഞാൻ വഴിപിഴച്ചിരിക്കുന്നു, ഞാൻ സന്മാർഗം ലഭിച്ചവരിൽ പെട്ടവനാകുകയുമില്ല. എന്നാൽ ഈ പ്രശ്നത്തിൽ നബി(സ)യുടെ വിധി ഞാൻ വിധിക്കാം: മകൾക്ക് പകുതി, മകന്റെ മകൾക്ക് മൂന്നിൽ രണ്ടിന്റെ പൂർത്തീകരണമായ വിഹിതം, ശേഷിച്ചത് പിതാവും മാതാവുമൊത്ത സഹോദരിക്കും. (ബു,ദ,തു,ന,ജ)', 'هُزَيْلِ بْنِ شُرَحْبِيلَ الْأَوْدِيِّ قَالَ', 'ഹുസൈലുബ്നു ശുറഹ്ബീലിൽ ഔദീ(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 604, 604, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ، أَنَّهُ سُئِلَ عَنِ ابْنَةٍ وَابْنَةِ ابْنٍ وَأُخْتٍ، فَقَالَ: لِلْإِبْنَةِ النِّصْفُ، وَلِلْأُخْتِ النِّصْفُ، وَأْتِ ابْنَ مَسْعُودٍ فَسَيُتَابِعُنِي. فَسُئِلَ ابْنُ مَسْعُودٍ وَأُخْبِرَ بِقَوْلِ أَبِي مُوسَى، فَقَالَ: لَقَدْ ضَلَلْتُ إِذًا وَمَا أَنَا مِنَ الْمُهْتَدِينَ، أَقْضِي فِيهَا بِمَا قَضَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لِلِابْنَةِ النِّصْفُ، وَلِابْنَةِ ابْنِ السُّدُسُ تَكْمِلَةَ الثُّلُثَيْنِ، وَمَا بَقِيَ فَلِلْأُخْتِ، فَأُخْبِرَ أَبُو مُوسَى بِقَوْلِ ابْنِ مَسْعُودٍ، فَقَالَ: لَا تَسْأَلُونِي مَا دَامَ هَذَا الْحَبْرُ فِيكُمْ. (خ,د,ت,ن,جه)', 'അബൂമൂസ(റ): മകളുടെയും മകന്റെ മകളുടെയും സഹോദരിയുടെയും അനന്തരാവകാശ ഓഹരിയെക്കുറിച്ച് അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: മകൾക്ക് പകുതി, സഹോദരിക്ക് പകുതി. ഇനി നീ ഇബ്നുമസ്ഊദ്(റ)വിനെ സമീപിക്കുക, അദ്ദേഹവും സമാനമായ വിധിയാണ് പറയുക. അങ്ങനെ ഇബ്നുമസ്ഊദ്(റ)വിനോട് ചോദിക്കപ്പെടുകയും അബൂമൂസ(റ)വിന്റെ വിധി വിശദീകരിച്ചുകൊടുക്കുകയും ചെയ്തു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അങ്ങനെയെങ്കിൽ ഞാൻ വഴിപിഴച്ചവനാകും, ഞാൻ സന്മാർഗം ലഭിച്ചവരിൽ പെട്ടവനാകുകയുമില്ല. എന്നാൽ, ഈ വിഷയത്തിൽ നബി(സ) വിധിച്ചത് ഞാൻ വിധിക്കുന്നു: മകൾക്ക് പകുതി, മകന്റെ മകൾക്ക് മൂന്നിൽ രണ്ടിന്റെ പൂർത്തീകരണമായ ആറിലൊന്ന്, ബാക്കി ഓഹരി സഹോദരിക്കും. ശേഷം ഇബ്നുമസ്ഊദ്(റ)വിന്റെ മറുപടി അബൂമൂസ(റ)വിനെ അറിയിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നിങ്ങളിൽ ആ മഹാപണ്ഡിതനുള്ള കാലത്തോളം എന്നോട് നിങ്ങൾ ഒന്നും ചോദിക്കരുത്. (ബു,ദ,തു,ന,ജ)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 604, 605, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: جَاءَتِ امْرَأَةُ سَعْدِ بْنِ الرَّبِيعِ بِابْنَتَيْهَا مِنْ سَعْدٍ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ: يَا رَسُولَ اللَّهِ، هَاتَانِ ابْنَتَا سَعْدِ بْنِ الرَّبِيعِ، قُتِلَ أَبُوهُمَا مَعَكَ يَوْمَ أُحُدٍ شَهِيدًا، وَإِنَّ عَمَّهُمَا أَخَذَ مَالَهُمَا فَلَمْ يَدَعْ لَهُمَا مَالاً، وَلَا تُنْكَحَانِ إِلَّا وَلَهُمَا مَالٌ؟ قَالَ: "يَقْضِي اللَّهُ فِي ذَلِكَ". فَنَزَلَتْ آيَةُ الْمِيرَاثِ، فَبَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى عَمِّهِمَا فَقَالَ: "أَعْطِ ابْنَتَيْ سَعْدٍ الثُّلُثَيْنِ، وَأَعْطِ أُمَّهُمَا الثُّمُنَ، وَمَا بَقِيَ فَهُوَ لَكَ". حَسَنٌ صَحِيحٌ. (د,ت,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): സഅ്ദുബ്നു റബീഅ്(റ)വിന്റെ പത്നി സഅ്ദ്(റ)വിൽ പിറന്ന രണ്ട് പെൺകുട്ടികളെ കൂട്ടി നബി(സ)യുടെ സന്നിധിയിൽ വന്ന് പറഞ്ഞു: റസൂലേ, ഇവർ സഅ്ദുബ്നു റബീഅ്(റ)വിന്റെ പുത്രികളാണ്. ഇവരുടെ പിതാവ് അങ്ങയുടെ കൂടെ ഉഹ്ദിൽ പങ്കെടുത്ത് രക്തസാക്ഷിത്വം വരിച്ചു. ഇവരുടെ പിതൃസഹോദരൻ ധനം ഇവർക്കു നൽകാതെ കയ്യടക്കിയിരിക്കുകയാണ്. ധനമില്ലാതെ ഒരാളും ഇവരെ വിവാഹം കഴിക്കുകയില്ല. തിരുമേനി(സ) പറഞ്ഞു: "ഈ പ്രശ്നത്തിൽ അല്ലാഹു വിധികൽപിക്കും." അന്നേരം അനന്തരാവകാശത്തെക്കുറിച്ചുള്ള സൂക്തമിറങ്ങി. ഉടനെ റസൂലുല്ലാഹി(സ) അവരുടെ പിതൃസഹോദരനിലേക്ക് ആളെ അയച്ചുകൊണ്ട് പറഞ്ഞു: "സഅ്ദിന്റെ രണ്ട് മക്കൾക്ക് മൂന്നിൽ രണ്ട് ഭാഗം നൽകുക. അവരുടെ മാതാവിന് എട്ടിലൊന്ന് നൽകുക. ബാക്കിയുള്ളത് നിനക്കുള്ളതുമാണ്." (ദ,തു,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 605, 605, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى جِئْنَا امْرَأَةً مِنَ الْأَنْصَارِ فِي الْأَسْوَاقِ، فَجَاءَتِ الْمَرْأَةُ بِابْنَتَيْنِ لَهَا فَقَالَتْ: يَا رَسُولَ اللَّهِ، هَاتَانِ بِنْتَا ثَابِتِ بْنِ قَيْسٍ، قُتِلَ مَعَكَ يَوْمَ أُحُدٍ، وَقَدِ اسْتَفَاءَ عَمُّهُمَا مَالَهُمَا وَمِيرَاثَهُمَا كُلَّهُ، فَلَمْ يَدَعْ لَهُمَا مَالاً إِلَّا أَخَذَهُ، فَمَا تَرَى يَا رَسُولَ اللَّهِ؟ فَوَاللَّهِ لَا تُنْكَحَانِ أَبَدًا إِلَّا وَلَهُمَا مَالٌ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَقْضِي اللَّهُ فِي ذَلِكَ". قَالَ: وَنَزَلَتْ سُورَةُ النِّسَاءِ: {يُوصِيكُمُ اللهُ فِي أَوْلَادِكُمْ} الْآيَةَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ادْعُوا لِي الْمَرْأَةَ وَصَاحِبَهَا". فَقَالَ لِعَمِّهِمَا: "أَعْطِهِمَا الثُّلُثَيْنِ وَأَعْطِ أُمَّهُمَا الثُّمُنَ وَمَا بَقِيَ فَلَكَ".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=9 and h.hadith_no=9), 1, 'وَفِي رِوَايَةٍ: أَنَّ امْرَأَةَ سَعْدِ بْنِ الرَّبِيعِ قَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ سَعْدًا هَلَكَ وَتَرَكَ ابْنَتَيْنِ. وَسَاقَ نَحْوَهُ، قَالَ أَبُو دَاوُدَ: وَهَذَا هُوَ أَصَحُّ. (ق,د,ت,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: സഅ്ദുബ്നു റബീഅ്(റ)വിന്റെ ഭാര്യ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, രണ്ട് പെൺമക്കളെ ഉപേക്ഷിച്ച് സഅ്ദ്(റ) മരിച്ചു. ശേഷം മുമ്പ് പറഞ്ഞതുപോലെ ഹദീസ് പൂർത്തിയാക്കി. അബൂദാവുദ്(റ) പറയുന്നു: ഇതാണ് ഏറ്റവും സ്വീകാര്യമായത്. (ബു,മു,ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنِ الْأَسْوَدِ بْنِ يَزِيدَ: أَنَّ مُعَاذَ بْنَ جَبَلٍ وَرَّثَ أُخْتًا وَابْنَةً، فَجَعَلَ لِكُلِّ وَاحِدَةٍ مِنْهُمَا النِّصْفَ، وَهُوَ بِالْيَمَنِ، وَنَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَئِذٍ حَيٌّ. (خ,د)', 'അസ്വദുബ്നു യസീദ്(റ): മുആദുബ്നു ജബൽ(റ) യമനിലായിരിക്കെ, മകൾക്കും സഹോദരിക്കുമിടയിൽ അനന്തരസ്വത്ത് വീതിച്ചു. അങ്ങനെ അവർ രണ്ടുപേർക്കും പകുതി നൽകി. ആ സമയം തിരുമേനി(സ) ജീവിച്ചിരിപ്പുണ്ടായിരുന്നു. (ബു,ദ)', 'الْأَسْوَدِ بْنِ يَزِيدَ', 'അസ്വദുബ്നു യസീദ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 606, 606, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ: قَالَ: ثَلاثٌ، لَأَنْ يَكُونَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيَّنَهُنَّ، أَحَبُّ إِلَيَّ مِنَ الدُّنْيَا وَمَا فِيهَا: الْكَلالَةُ وَالرِّبَا وَالْخِلافَةُ. [ز: مُنْقَطِعٌ] (جه)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): മൂന്ന് കാര്യങ്ങൾ, റസൂൽ(സ) വ്യക്തമാക്കിയിരുന്നുവെങ്കിൽ അതാകുമായിരുന്നു ഐഹികലോകത്തെക്കാളും അതിലെ സകലതിനേക്കാളും എനിക്ക് ഇഷ്ടപ്പെട്ടത്. കലാലത്ത്, പലിശ, ഖിലാഫത്ത് എന്നിവയാണവ. (ജ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: مُنْقَطِعٌ', null, 606, 606, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ مَعْدَانَ بْنِ أَبِي طَلْحَةَ: أَنَّ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ خَطَبَ يَوْمَ جُمُعَةٍ، فَذَكَرَ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَذَكَرَ أَبَا بَكْرٍ رَضِيَ اللَّهُ عَنْهُ، ثُمَّ قَالَ: إِنِّي لَا أَدَعُ بَعْدِي شَيْئًا أَهَمَّ عِنْدِي مِنَ الْكَلالَةِ، مَا رَاجَعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي شَيْءٍ مَا رَاجَعْتُهُ فِي الْكَلالَةِ، وَمَا أَغْلَظَ لِي فِي شَيْءٍ مَا أَغْلَظَ لِي فِيهِ، حَتَّى طَعَنَ بِإِصْبَعِهِ فِي صَدْرِي، وَقَالَ: "يَا عُمَرُ، أَلَا تَكْفِيكَ آيَةُ الصَّيْفِ الَّتِي فِي آخِرِ سُورَةِ النِّسَاءِ". وَإِنِّي إِنْ أَعِشْ أَقْضِ فِيهَا بِقَضِيَّةٍ يَقْضِي بِهَا مَنْ يَقْرَأُ الْقُرْآنَ وَمَنْ لَا يَقْرَأُ الْقُرْآنَ. (م)', 'മഅ്ദാനുബ്നു അബീത്വൽഹ(റ): വെള്ളിയാഴ്ച ദിവസം ഉമർ(റ) പ്രസംഗിച്ചു. നബി(സ)യെക്കുറിച്ചും അബൂബക്കർ(റ)വിനെക്കുറിച്ചും പരാമർശിച്ചു. എന്നിട്ട് പറഞ്ഞു: കലാലത്തിനേക്കാൾ പ്രാധാന്യമേറിയ ഒരു വിഷയവും എന്റെ കാലശേഷം ഞാൻ ഒഴിവാക്കിയിടുന്നില്ല. കലാലത്തിന്റെ വിഷയത്തിൽ ഞാൻ റസൂൽ(സ)യോട് തുടരെത്തുടരെ ചോദിച്ചതുപോലെ ഒരു വിഷയത്തെക്കുറിച്ചും ചോദിച്ചിട്ടില്ല. കലാലത്തിനെക്കുറിച്ച് റസൂൽ(സ) എന്നോട് ശക്തമായി സംസാരിച്ചതു പോലെ മറ്റൊന്നിലും എന്നോട് ശക്തമായി സംസാരിച്ചിട്ടില്ല. എത്രത്തോളമെന്നാൽ എന്റെ നെഞ്ചിൽ വിരൽ കൊണ്ട് കുത്തിയിട്ട് അവിടുന്ന് പറഞ്ഞു: "ഉമറേ, സൂറത്തുന്നിസാഇന്റെ അവസാനത്തിലെ ആയത്തുസ്വൈഫ് തന്നെ നിനക്ക് മതിയാവുകയില്ലേ" ഞാൻ ജീവിച്ചിരിക്കുമ്പോൾ, ഖുർആൻ പാരായണം ചെയ്യുന്നവനും പാരായണം ചെയ്യാത്തവനും വിധിക്കുന്ന വിധിയായിരിക്കും ഈ വിഷയത്തിൽ ഞാൻ വിധിക്കുന്നത്. (മു)', 'مَعْدَانَ بْنِ أَبِي طَلْحَةَ', 'മഅ്ദാനുബ്നു അബീത്വൽഹ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 606, 606, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: مَرِضْتُ، فَأَتَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعُودُنِي، فَوَجَدَنِي قَدْ أُغْمِيَ عَلَيَّ، فَأَتَى وَمَعَهُ أَبُو بَكْرٍ وَعُمَرُ - رَضِيَ اللَّهُ عَنْهُمَا - وَهُمَا مَاشِيَانِ، فَتَوَضَّأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَبَّ عَلَيَّ مِنْ وَضُوئِهِ فَأَفَقْتُ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، كَيْفَ أَقْضِي فِي مَالِي؟ أَوْ: كَيْفَ أَصْنَعُ فِي مَالِي؟ فَلَمْ يُجِبْنِي شَيْئًا، وَكَانَ لَهُ تِسْعُ أَخَوَاتٍ، حَتَّى نَزَلَتْ آيَةُ الْمِيرَاثِ: {يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلالَةِ} الْآيَةَ [النساء: ١٧٦] قَالَ جَابِرٌ: فِيَّ نَزَلَتْ. حَسَنٌ صَحِيحٌ. (د,ت,جه)', 'ജാബിർ(റ): എനിക്ക് അസുഖം ബാധിച്ചു. റസൂൽ(സ) എന്നെ സന്ദർശിക്കാൻ വന്നു. ഞാൻ ബോധരഹിതനാണെന്ന് തിരുമേനി(സ) മനസ്സിലാക്കി. നബി(സ) വരുമ്പോൾ അവിടുത്തോടൊപ്പം അബൂബക്കർ(റ)വും ഉമർ(റ)വും ഉണ്ടായിരുന്നു. അവരിരുവരും നടന്നാണ് വന്നത്. റസൂൽ(സ) അംഗശുദ്ധി വരുത്തി. അംഗശുദ്ധി വരുത്തിയ വെള്ളത്തിൽ നിന്ന് അൽപം എന്റെ ശരീരത്തിൽ തെളിച്ചു. എനിക്ക് ബോധം തിരിച്ചുകിട്ടി. ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ എന്റെ സമ്പത്തിൽ എങ്ങനെയാണ് വിധിക്കേണ്ടത്? അല്ലെങ്കിൽ ഞാൻ എന്റെ സമ്പത്ത് എന്താണ് ചെയ്യേണ്ടത്? റസൂൽ(സ) എന്നോട് മറുപടിയായി ഒന്നും പറഞ്ഞില്ല. അദ്ദേഹത്തിന് ഒമ്പത് സഹോദരിമാരാണ് ഉണ്ടായിരുന്നത്. അങ്ങനെ അനന്തരാവകാശത്തെ പ്രതിപാദിക്കുന്ന സൂക്തമിറങ്ങി: ''അവർ താങ്കളോട് മതവിധി തേടുന്നു. താങ്കൾ പറയുക: കലാലത്തിന്റെ (മാതാപിതാക്കളും സന്താനങ്ങളുമല്ലാത്ത അനന്തരാവകാശികൾ) വിഷയത്തിൽ അല്ലാഹു നിങ്ങൾക്ക് മതവിധി തരുന്നു.'' (നിസാഅ്: 176) ജാബിർ(റ) പറയുന്നു: എന്റെ കാര്യത്തിലാണ് ഈ സൂക്തമിറങ്ങിയത്. (ദ,തു,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], 'النساء: ١٧٦', null, 607, 607, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: اشْتَكَيْتُ وَعِنْدِي سَبْعُ أَخَوَاتٍ، فَدَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَنَفَخَ فِي وَجْهِي فَأَفَقْتُ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَلَا أُوصِي لِأَخَوَاتِي بِالثُّلُثِ؟ قَالَ: "أَحْسِنْ". قُلْتُ: الشَّطْرُ؟ قَالَ: "أَحْسِنْ". ثُمَّ خَرَجَ وَتَرَكَنِي، فَقَالَ: "يَا جَابِرُ، لَا أُرَاكَ مَيِّتًا مِنْ وَجَعِكَ هَذَا، وَإِنَّ اللَّهَ قَدْ أَنْزَلَ فَبَيَّنَ الَّذِي لِأَخَوَاتِكَ، فَجَعَلَ لَهُنَّ الثُّلُثَيْنِ". قَالَ: فَكَانَ جَابِرٌ يَقُولُ: أُنْزِلَتْ هَذِهِ الْآيَةُ فِيَّ: {يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلالَةِ} [النساء: ١٧٦]. (د)', 'ജാബിർ(റ): ഞാൻ രോഗബാധിതനായി. അന്ന് എനിക്ക് ഏഴ് സഹോദരിമാരുണ്ടായിരുന്നു. റസൂൽ(സ) എന്റെ അടുത്തേക്ക് വരികയും എന്റെ മുഖത്ത് ഊതുകയും എനിക്ക് ബോധം തിരിച്ചുകിട്ടുകയും ചെയ്തു. ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ സഹോദരിമാർക്ക് മൂന്നിലൊന്ന് നൽകണമെന്ന് ഞാൻ വസ്വിയത്ത് ചെയ്യട്ടെയോ? റസൂൽ(സ) പറഞ്ഞു: "നീ നല്ലതു ചെയ്യുക." ഞാൻ പറഞ്ഞു: പകുതി? അവിടുന്ന് പറഞ്ഞു: "നീ നല്ലത് ചെയ്യുക." ശേഷം റസൂൽ(സ) എന്നെ വിട്ടേച്ചുപോയി. അവിടുന്ന് പറഞ്ഞു: "ജാബിറേ, ഈ രോഗം മൂലം നീ മരിക്കുമെന്ന് എനിക്ക് തോന്നുന്നില്ല. അല്ലാഹു സൂക്തമിറക്കുകയും അതിൽ നിന്റെ സഹോദരിമാർക്കുള്ളത് വ്യക്തമാക്കുകയും ചെയ്തിരിക്കുന്നു. അവർക്ക് മൂന്നിൽ രണ്ടാണ് അല്ലാഹു നിശ്ചയിച്ചിരിക്കുന്നത്." നിവേദകൻ പറയുന്നു: ജാബിർ(റ) പറയുമായിരുന്നു: ''അവർ താങ്കളോട് മതവിധി തേടുന്നു. താങ്കൾ പറയുക: കലാലത്തിനെക്കുറിച്ച് അല്ലാഹു നിങ്ങൾക്ക് മതവിധി നൽകും'' (നിസാഅ്: 176) എന്ന സൂക്തം എന്റെ കാര്യത്തിലാണ് ഇറങ്ങിയത്. (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'النساء: ١٧٦', null, 607, 607, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، ''يَسْتَفْتُونَكَ فِي الْكَلالَةِ''، فَمَا الْكَلالَةُ؟ قَالَ: "تُجْزِيكَ آيَةُ الصَّيْفِ". (د,ت)', 'ബറാഅ്ബിൻ ആസിബ്(റ): ഒരാൾ നബി(സ)യെ സമീപിച്ച് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ''കലാലത്തിനെക്കുറിച്ച് അവർ അങ്ങയോട് മതവിധി ചോദിക്കുന്നു'' എന്ന സൂക്തത്തിൽ കലാലത്ത് എന്നാൽ എന്താണ്? അവിടന്ന് പറഞ്ഞു: "സ്വൈഫിന്റെ സൂക്തം നിനക്ക് മതിയായതാണ്." (ദ,തു)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഅ്ബിൻ ആസിബ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 607, 607, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ آخِرَ سُورَةٍ أُنْزِلَتْ تَامَّةً سُورَةُ التَّوْبَةِ، وَأَنَّ آخِرَ آيَةٍ أُنْزِلَتْ آيَةُ الْكَلالَةِ. (م)', 'ബറാഅ്ബ്നുആസിബ്(റ): അവസാനമിറങ്ങിയ പൂർണ്ണമായ സൂറത്ത് തൗബാ സൂറതാണ്. അവസാനമിറങ്ങിയ സൂക്തം കലാലത്തിന്റെ സൂക്തവുമാണ്. (മു)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഅ്ബ്നുആസിബ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 608, 608, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ: إِنَّكُمْ تَقْرَءُونَ هَذِهِ الْآيَةَ: {مِنْ بَعْدِ وَصِيَّةٍ تُوصُونَ بِهَا أَوْ دَيْنٍ} [النساء: ١٢] وَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى بِالدَّيْنِ قَبْلَ الْوَصِيَّةِ. وَإِنَّ أَعْيَانَ بَنِي الْأُمِّ يَتَوَارَثُونَ دُونَ بَنِي الْعَلَّاتِ، الرَّجُلُ يَرِثُ أَخَاهُ لِأَبِيهِ وَأُمِّهِ دُونَ أَخِيهِ لِأَبِيهِ. (ت,جه)', 'അലി(റ): നിങ്ങൾ ഈ സൂക്തം ഓതാറില്ലേ: ''നിങ്ങൾ ചെയ്യുന്ന വസ്വിയ്യത്തിനും കടത്തിനും ശേഷം'' (നിസാഅ്: 12). നിശ്ചയം വസ്വിയ്യതിനു മുമ്പ് കടം പരിഗണിക്കണമെന്ന് റസൂൽ(സ) വിധിച്ചു. മാതാവും പിതാവുമൊത്ത സഹോദരങ്ങൾ പരസ്പരം അനന്തരമെടുക്കും, പിതാവൊത്ത സഹോദരങ്ങൾ അപ്രകാരമല്ല. ഒരാൾ മാതാവും പിതാവുമൊത്ത തന്റെ സഹോദരനെ അനന്തരമെടുക്കും, പിതാവൊത്ത സഹോദരനെ അനന്തരമെടുക്കുകയില്ല. (തു,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], 'النساء: ١٢', null, 608, 608, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: قَالَ جَاءَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعُودُنِي وَأَنَا مَرِيضٌ فِي بَنِي سَلَمَةَ، فَقُلْتُ: يَا نَبِيَّ اللَّهِ، كَيْفَ أَقْسِمُ مَالِي بَيْنَ وَلَدِي؟ فَلَمْ يَرُدَّ عَلَيَّ شَيْئًا، فَنَزَلَتْ: {يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ} الْآيَةَ [النساء: ١١] حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഞാൻ ബനൂസലമയിൽ രോഗിയായി കിടക്കവേ, റസൂൽ(സ) എന്നെ സന്ദർശിക്കാനെത്തി. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ മക്കൾക്കിടയിൽ ഞാൻ എങ്ങനെയാണ് വീതിക്കേണ്ടത്. നബി(സ) മറുപടിയൊന്നും പറഞ്ഞില്ല. അപ്പോൾ ''നിങ്ങളുടെ സന്താനങ്ങളുടെ കാര്യത്തിൽ അല്ലാഹു നിങ്ങൾക്ക് നിർദ്ദേശം നൽകുന്നു, ആണിന് രണ്ട് പെണ്ണിന്റേതിന് തുല്ല്യമായ ഓഹരിയാണ് ഉള്ളത്'' (നിസാഅ്: 11) എന്ന സൂക്തമിറങ്ങി. (ബു,മു,ദ,തു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], 'النساء: ١١', null, 608, 608, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اقْسِمِ الْمَالَ بَيْنَ أَهْلِ الْفَرَائِضِ عَلَى كِتَابِ اللَّهِ، فَمَا تَرَكَتِ الْفَرَائِضُ فَلِأَوْلَى ذَكَرٍ". (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "വിഹിതം നിശ്ചയിക്കപ്പെട്ട അനന്തരാവകാശികൾക്കിടയിൽ അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിലുള്ളത് പ്രകാരം നിങ്ങൾ വീതിക്കുക. വിഹിതം നിശ്ചയിക്കപ്പെട്ടവർക്കിടയിൽ വീതിച്ചതിന് ശേഷം ബാക്കിയുള്ളത് ഏറ്റവുമടുത്ത പുരുഷനുള്ളതാണ്." (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 608, 609, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَجُلاً أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ ابْنَ ابْنِي مَاتَ، فَمَا لِي مِنْ مِيرَاثِهِ؟ فَقَالَ: "لَكَ السُّدُسُ". فَلَمَّا أَدْبَرَ دَعَاهُ، فَقَالَ: "لَكَ سُدُسٌ آخَرُ". فَلَمَّا أَدْبَرَ دَعَاهُ، فَقَالَ: "إِنَّ السُّدُسَ الْآخَرَ طُعْمَةٌ". (د,ت)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): ഒരാൾ നബി(സ)യെ സമീപിച്ച് ചോദിച്ചു: എന്റെ മകന്റെ മകൻ മരിച്ചു. അവന്റെ അനന്തരസ്വത്തിൽ നിന്ന് എന്റെ വിഹിതമെത്രയാണ്. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് ആറിലൊന്നാണുള്ളത്." അയാൾ പിന്തിരിഞ്ഞ് പോയപ്പോൾ റസൂൽ(സ) അയാളെ വീണ്ടും വിളിച്ചിട്ട് പറഞ്ഞു: "നിങ്ങൾക്ക് മറ്റൊരു ആറിലൊന്ന് കൂടിയുണ്ട്." അയാൾ പിന്തിരിഞ്ഞപ്പോൾ വീണ്ടും അവിടന്ന് അയാളെ വിളിച്ചിട്ട് പറഞ്ഞു: "മറ്റൊരു ആറിലൊന്ന് നിങ്ങൾക്ക് ഭക്ഷണത്തിനുള്ളതാണ്." (ദ,തു)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 609, 609, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَيُّكُمْ يَعْلَمُ مَا وَرَّثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْجَدَّ؟ فَقَالَ مَعْقِلُ بْنُ يَسَارٍ: أَنَا، وَرَّثَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ السُّدُسَ. قَالَ: مَعَ مَنْ؟ قَالَ: لَا أَدْرِي، قَالَ: لَا دَرَيْتَ، فَمَا تُغْنِي إِذًا. (د,جه)', 'ഉമർ(റ): അദ്ദേഹം ചോദിച്ചു: പിതാമഹന് റസൂൽ(സ) അനന്തരവിഹിതം നിശ്ചയിച്ചത് എത്രയാണെന്ന് നിങ്ങളിലാർക്കാണറിയുക. മഅ്ഖിലുബ്നു യസാർ(റ) പറഞ്ഞു: എനിക്കറിയാം. ആറിലൊന്നാണ് നബി(സ) നിശ്ചയിച്ചത്. ഉമർ(റ) ചോദിച്ചു: ആരോടൊപ്പമാണ് (ആ വിഹിതം പങ്കിടുന്നത്)? അദ്ദേഹം പറഞ്ഞു: എനിക്കറിയില്ല. ഉമർ(റ) പറഞ്ഞു: അതറിയില്ലെങ്കിൽ നിന്നെക്കൊണ്ട് കാര്യവുമില്ല. (ദ,ജ)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 609, 609, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ مَعْقِلِ بْنِ يَسَارٍ الْمُزَنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِفَرِيضَةٍ فِيهَا جَدٌّ، فَأَعْطَاهُ ثُلُثًا. أَوْ: سُدُسًا. (جه)', 'മഅ്ഖിലുബ്നു യസാറിൽ മുസ്നി(റ): പിതാമഹൻ ഉൾപെടുന്ന ഒരു ഓഹരി സംബന്ധമായ കേസ് നബി(സ)യുടെ മുന്നിലെത്തി എന്ന് ഞാൻ കേട്ടു. അപ്പോൾ അവിടന്ന് പിതാമഹന് മൂന്നിലൊന്ന്, അല്ലെങ്കിൽ ആറിലൊന്ന് അനന്തരവിഹിതം നൽകി. (ജ)', 'مَعْقِلِ بْنِ يَسَارٍ الْمُزَنِيِّ', 'മഅ്ഖിലുബ്നു യസാറിൽ മുസ്നി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 609, 609, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ مَعْقِلِ بْنِ يَسَارٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي جَدٍّ كَانَ فِينَا بِالسُّدُسِ. (د,جه)', 'മഅ്ഖിലുബ്നു യസാർ(റ): ഞങ്ങളിലെ ഒരു പിതാമഹന് റസൂൽ(സ) അനന്തരവിഹിതം ആറിലൊന്നായി വിധിച്ചു. (ദ,ജ)', 'مَعْقِلِ بْنِ يَسَارٍ', 'മഅ്ഖിലുബ്നു യസാർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 609, 609, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ قَبِيصَةَ بْنِ ذُؤَيْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَتِ الْجَدَّةُ إِلَى أَبِي بَكْرٍ الصِّدِّيقِ - رَضِيَ اللَّهُ عَنْهُ - تَسْأَلُهُ مِيرَاثَهَا، فَقَالَ لَهَا أَبُو بَكْرٍ: مَا لَكِ فِي كِتَابِ اللَّهِ شَيْءٌ، وَمَا عَلِمْتُ لَكِ فِي سُنَّةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْئًا، فَارْجِعِي حَتَّى أَسْأَلَ النَّاسَ. فَسَأَلَ النَّاسَ، فَقَالَ الْمُغِيرَةُ بْنُ شُعْبَةَ رَضِيَ اللَّهُ عَنْهُ: حَضَرْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْطَاهَا السُّدُسَ. فَقَالَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: هَلْ مَعَكَ غَيْرُكَ؟ فَقَامَ مُحَمَّدُ بْنُ مَسْلَمَةَ الْأَنْصَارِيُّ فَقَالَ مِثْلَ مَا قَالَ الْمُغِيرَةُ بْنُ شُعْبَةَ، فَأَنْفَذَهُ لَهَا أَبُو بَكْرٍ. ثُمَّ جَاءَتِ الْجَدَّةُ الْأُخْرَى - مِنْ قِبَلِ الْأَبِ - إِلَى عُمَرَ، تَسْأَلُهُ مِيرَاثَهَا. فَقَالَ: مَا لَكِ فِي كِتَابِ اللَّهِ شَيْءٌ، وَمَا كَانَ الْقَضَاءُ الَّذِي قُضِيَ بِهِ إِلَّا لِغَيْرِكِ، وَمَا أَنَا بِزَائِدٍ فِي الْفَرَائِضِ شَيْئًا، وَلَكِنْ هُوَ ذَاكِ السُّدُسُ، فَإِنِ اجْتَمَعْتُمَا فِيهِ فَهُوَ بَيْنَكُمَا، وَأَيَّتُكُمَا خَلَتْ بِهِ فَهُوَ لَهَا. (د,ت,جه)', 'ഖുബൈസ്ബ്നുദുഐബ്(റ): ഒരു വല്ല്യുമ്മ തന്റെ അനന്തരവിഹിതം ചോദിച്ച് കൊണ്ട് അബൂബക്കർ(റ)വിനെ സമീപിച്ചു. അപ്പോൾ അബൂബക്കർ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിൽ നിനക്ക് ഒരു വിഹിതവും പറഞ്ഞിട്ടില്ല. നബി(സ)യുടെ ചര്യയിലും നിനക്ക് ഒരു വിഹിതമുള്ളതായി എനിക്കറിയില്ല. നീ പോയി വരൂ, ഞാൻ ഇതിനെക്കുറിച്ച് ജനങ്ങളോട് ചോദിക്കട്ടെ. അങ്ങനെ അദ്ദേഹം ജനങ്ങളോട് ചോദിച്ചു. അപ്പോൾ മുഗീറതുബ്നുശുഅ്ബ(റ) പറഞ്ഞു: റസൂൽ(സ) അവർക്ക് ആറിലൊന്ന് നൽകുന്നതിന് ഞാൻ സാക്ഷിയായിട്ടുണ്ട്. അബൂബക്കർ(റ) ചോദിച്ചു: നിന്റെ കൂടെ നീയല്ലാതെ വേറെയാരെങ്കിലുമുണ്ടോ. അപ്പോൾ മുഹമ്മദ്ബ്നു മസ്ലമതുൽ അൻസാരി(റ) എഴുന്നേറ്റ് നിന്ന് മുഗീറ(റ) പറഞ്ഞത് പോലെ പറഞ്ഞു. അപ്പോൾ അബൂബക്കർ(റ) അവർക്കത് അനുവദിച്ച് കൊടുത്തു. പിന്നെ പിതാവ് വഴിക്കുള്ള മറ്റൊരു വല്ല്യുമ്മ ഉമർ(റ)വിനെ സമീപിച്ച് തന്റെ അനന്തരവിഹിതം ചോദിച്ചു. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിൽ നിനക്ക് ഒന്നും തന്നെ നിശ്ചയിച്ചിട്ടില്ല. മുമ്പ് വിധിക്കപ്പെട്ട വിധി നിന്റെ വിഷയത്തിലല്ലതാനും. (അഥവാ ആദ്യം വന്നത് ഉമ്മയുടെ ഉമ്മയും ഇപ്പോൾ വന്നത് ഉപ്പയുടെ ഉമ്മയുമാണ്. അല്ലെങ്കിൽ നേരേ മറിച്ച്) അനന്തര സ്വത്തിൽ കൂട്ടിച്ചേർക്കാൻ ഞാൻ ഉദ്ദേശിക്കുന്നുമില്ല. എങ്കിലും ആ ആറിലൊന്നിൽ നിങ്ങൾ രണ്ട് കൂട്ടരുമുണ്ടെങ്കിൽ രണ്ട് കൂട്ടർക്കുമിടയിൽ അത് വീതിക്കണം. ഇനി ഒറ്റക്കാണെങ്കിൽ അത് പൂർണ്ണമായും അവൾക്കുള്ളതായിരിക്കും. (ദ,തു,ജ)', 'قَبِيصَةَ بْنِ ذُؤَيْبٍ', 'ഖുബൈസ്ബ്നുദുഐബ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 609, 610, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرَّثَ جَدَّةً سُدُسًا. [فِي إِسْنَادِهِ مُدَلَّسٌ عَنْعَنَهُ] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) വല്ല്യുമ്മക്ക് ആറിലൊന്ന് അനന്തരം നൽകി. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'فِي إِسْنَادِهِ مُدَلَّسٌ عَنْعَنَهُ', null, 610, 610, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَعَلَ لِلْجَدَّةِ السُّدُسَ، إِذَا لَمْ يَكُنْ دُونَهَا أُمٌّ. (د)', 'ബുറൈദ(റ): വല്ല്യുമ്മക്ക് താഴെ മാതാവില്ലെങ്കിൽ അവരുടെ അനന്തരവിഹിതം ആറിലൊന്നായി നബി(സ) നിശ്ചയിച്ചു. (ദ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 610, 610, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ، قَالَ فِي الْجَدَّةِ مَعَ ابْنِهَا: إِنَّهَا أَوَّلُ جَدَّةٍ أَطْعَمَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُدُسًا مَعَ ابْنِهَا، وَابْنُهَا حَيٌّ. (ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): തന്റെ മകനോടൊപ്പമുള്ള വല്യുമ്മയെക്കുറിച്ച് അദ്ദേഹം പറഞ്ഞു: തന്റെ മകൻ ജീവിച്ചിരിക്കെ മകനോടൊപ്പം റസൂൽ(സ) ആറിലൊന്ന് അനന്തരാവകാശമായി ഭക്ഷിപ്പിച്ച (നൽകിയ) ആദ്യത്തെ വല്യുമ്മയാണത്. (തു)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 610, 610, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَجُلاً رَمَى رَجُلاً بِسَهْمٍ فَقَتَلَهُ، وَلَيْسَ لَهُ وَارِثٌ إِلَّا خَالٌ، فَكَتَبَ فِي ذَلِكَ أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ رَضِيَ اللَّهُ عَنْهُ إِلَى عُمَرَ رَضِيَ اللَّهُ عَنْهُ، فَكَتَبَ إِلَيْهِ عُمَرُ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اللَّهُ وَرَسُولُهُ مَوْلَى مَنْ لَا مَوْلَى لَهُ وَالْخَالُ وَارِثُ مَنْ لَا وَارِثَ لَهُ". (ت,جه)', 'അബൂഉമാമ(റ): ഒരാൾ മറ്റൊരാളെ അമ്പെയ്തു കൊന്നു. മരണപ്പെട്ടവന് മാതൃസഹോദരനല്ലാതെ വേറെ ഒരു അനന്തരാവകാശിയുണ്ടായിരുന്നില്ല. ഇതേക്കുറിച്ച് ചോദിച്ചുകൊണ്ട് അബൂഉബൈദ(റ) ഉമർ(റ)വിന് കത്തെഴുതി. അപ്പോൾ ഉമർ(റ) മറുപടി എഴുതി: നബി(സ) പറഞ്ഞിരിക്കുന്നു: "രക്ഷിതാവില്ലാത്തവന്റെ രക്ഷിതാവ് അല്ലാഹുവും അവന്റെ റസൂലുമാണ്. അനന്തരാവകാശിയില്ലാത്തവന്റെ അനന്തരാവകാശിയാണ് മാതൃസഹോദരൻ." (തു,ജ)', 'أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ', 'അബൂഉമാമ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 611, 611, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنِ الْمِقْدَامِ أَبِي كَرِيمَةَ رَضِيَ اللَّهُ عَنْهُ - رَجُلٌ مِنْ أَهْلِ الشَّامِ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: "قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَرَكَ مَالاً فَلِوَرَثَتِهِ، وَمَنْ تَرَكَ كَلًّا فَإِلَيْنَا. وَرُبَّمَا قَالَ: فَإِلَى اللَّهِ وَإِلَى رَسُولِهِ. وَأَنَا وَارِثُ مَنْ لَا وَارِثَ لَهُ، أَعْقِلُ عَنْهُ وَأَرِثُهُ. وَالْخَالُ وَارِثُ مَنْ لَا وَارِثَ لَهُ، يَعْقِلُ عَنْهُ وَيَرِثُهُ". (د,جه)', 'മിഖ്ദാം അബീകരീമ(റ) - റസൂൽ(സ)യുടെ ശാമുകാരനായ അനുചരനാണ് അദ്ദേഹം - റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും വല്ല സമ്പത്തും ബാക്കിവെച്ചാൽ അത് അവന്റെ അനന്തരാവകാശികൾക്കുള്ളതാണ്. വല്ല ബാധ്യതയും ബാക്കിവെച്ചാൽ അത് നാം ഏറ്റെടുക്കും." ഒരുപക്ഷേ റസൂൽ(സ) പറഞ്ഞത് ഇപ്രകാരമാകാം: "അത് അല്ലാഹുവും റസൂലും ഏറ്റെടുക്കും. അനന്തരാവകാശിയില്ലാത്തവന്റെ അനന്തരാവകാശി ഞാനാണ്. ഞാനവന്റെ ബാധ്യതകൾ ഏറ്റെടുക്കുകയും അവനെ അനന്തരമെടുക്കുകയും ചെയ്യും. മാതൃസഹോദരൻ അനന്തരാവകാശി ഇല്ലാത്തവന്റെ അനന്തരാവകാശിയാണ്. അവൻ അവന്റെ ബാധ്യതകൾ ഏറ്റെടുക്കുകയും അനന്തരമെടുക്കുകയും ചെയ്യും." (ദ,ജ)', 'الْمِقْدَامِ أَبِي كَرِيمَةَ', 'മിഖ്ദാം അബീകരീമ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 611, 611, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنِ الْمِقْدَامِ الْكِنْدِي رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَنَا أَوْلَى بِكُلِّ مُؤْمِنٍ مِنْ نَفْسِهِ، فَمَنْ تَرَكَ دَيْنًا أَوْ ضَيْعَةً فَإِلَيَّ، وَمَنْ تَرَكَ مَالاً فَلِوَرَثَتِهِ، وَأَنَا مَوْلَى مَنْ لَا مَوْلَى لَهُ: أَرِثُ مَالَهُ، وَأَفُكُّ عَانِيَهُ. وَالْخَالُ مَوْلَى مَنْ لَا مَوْلَى لَهُ: يَرِثُ مَالَهُ، وَيَفُكُّ عَانِيَهُ". (د)', 'മിഖ്ദാം(റ): റസൂൽ(സ) പറഞ്ഞു: "ഓരോ വിശ്വാസിക്കും ഞാൻ അവന്റെ ആത്മാവിനേക്കാൾ അടുത്തവനാണ്. ആരെങ്കിലും വല്ല കടബാധ്യതയെയും അശരണ കുടുംബത്തെയും വിട്ടേച്ചുപോയാൽ അവയുടെ ഉത്തരവാദിത്തം എനിക്കായിരിക്കും. വല്ല സമ്പത്തും അവശേഷിപ്പിച്ചാൽ അത് അവന്റെ അനന്തരാവകാശികൾക്കുള്ളതായിരിക്കും. ഞാൻ രക്ഷിതാവില്ലാത്തവന്റെ രക്ഷിതാവാണ്. ഞാൻ അവനെ അനന്തരമെടുക്കുകയും അവന്റെ ബാധ്യതകൾ വീട്ടുകയും ചെയ്യും. മാതൃസഹോദരൻ രക്ഷിതാവില്ലാത്തവന്റെ രക്ഷിതാവാണ്. അവൻ അവനെ അനന്തരമെടുക്കുകയും അവന്റെ ബാധ്യതകൾ വീട്ടുകയും ചെയ്യും." (ദ)', 'الْمِقْدَامِ الْكِنْدِي', 'മിഖ്ദാം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 611, 611, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ مَوْلَى لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَاتَ وَتَرَكَ شَيْئًا، وَلَمْ يَدَعْ وَلَدًا وَلَا حَمِيمًا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَعْطُوا مِيرَاثَهُ رَجُلاً مِنْ أَهْلِ قَرْيَتِهِ". وَفِي رِوَايَةٍ: فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَاهُنَا أَحَدٌ مَنْ أَهْلِ أَرْضِهِ". قَالُوا: نَعَمْ. قَالَ: "فَأَعْطُوهُ مِيرَاثَهُ". (د,ت,جه)', 'ആഇശ(റ): നബി(സ)യുടെ ഒരടിമ മരണപ്പെട്ടു. അദ്ദേഹം കുറച്ച് സമ്പത്ത് അവശേഷിപ്പിച്ചിരിക്കുന്നു. എന്നാൽ അദ്ദേഹത്തിന് മക്കളോ അടുത്ത ബന്ധുക്കളോ ആരും തന്നെ ഇല്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവന്റെ അനന്തരസ്വത്ത് അവന്റെ ഗ്രാമക്കാരനായ ഒരാൾക്ക് നൽകുക." മറ്റൊരു നിവേദനം: നബി(സ) പറഞ്ഞു: "അവന്റെ നാട്ടുകാരെങ്കിലുമുണ്ടോ ഇവിടെ." അവർ പറഞ്ഞു: അതെ. അവിടുന്ന് പറഞ്ഞു: "എങ്കിൽ അനന്തരസ്വത്ത് അവന് നൽകുക." (ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 611, 611, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=9 and h.hadith_no=31), 1, 'وَفِي رِوَايَةٍ: فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَاهُنَا أَحَدٌ مَنْ أَهْلِ أَرْضِهِ". قَالُوا: نَعَمْ. قَالَ: "فَأَعْطُوهُ مِيرَاثَهُ". (د,ت,جه)', 'മറ്റൊരു നിവേദനം: നബി(സ) പറഞ്ഞു: "അവന്റെ നാട്ടുകാരെങ്കിലുമുണ്ടോ ഇവിടെ." അവർ പറഞ്ഞു: അതെ. അവിടുന്ന് പറഞ്ഞു: "എങ്കിൽ അനന്തരസ്വത്ത് അവന് നൽകുക." (ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ فَقَالَ: إِنَّ عِنْدِي مِيرَاثَ رَجُلٍ مِنَ الْأَزْدِ، وَلَسْتُ أَجِدُ أَزْدِيًّا أَدْفَعُهُ إِلَيْهِ؟ قَالَ: "اذْهَبْ، فَالْتَمِسْ أَزْدِيًّا حَوْلاً". قَالَ: فَأَتَاهُ بَعْدَ الْحَوْلِ فَقَالَ: يَا رَسُولَ اللَّهِ، لَمْ أَجِدْ أَزْدِيًّا أَدْفَعُهُ إِلَيْهِ؟ قَالَ: "فَانْطَلِقْ، فَانْظُرْ أَوَّلَ خُزَاعِيٍّ تَلْقَاهُ فَادْفَعْهُ إِلَيْهِ". فَلَمَّا وَلَّى قَالَ: "عَلَيَّ الرَّجُلَ". فَلَمَّا جَاءَهُ قَالَ: "انْظُرْ كُبْرَ خُزَاعَةَ فَادْفَعْهُ إِلَيْهِ". (د)', 'ബുറൈദ(റ): ഒരാൾ നബി(സ)യെ സമീപിച്ച് ഇപ്രകാരം പറഞ്ഞു: അസ്ദുകാരനായ ഒരാളുടെ അനന്തരസ്വത്ത് എന്റെ കൈവശമുണ്ട്. ഇത് കൈമാറാൻ ഒരു അസ്ദുകാരനെയും ഞാൻ ഇതുവരെ കണ്ടില്ല? തിരുമേനി(സ) പറഞ്ഞു: "നീ പോയി ഒരു വർഷം അസ്ദുകാരനെ തിരയുക." നിവേദകൻ പറയുന്നു: ഒരു വർഷത്തിന് ശേഷം അയാൾ വന്ന് പറഞ്ഞു: റസൂലേ, ഇതു നൽകാൻ ഒരു അസ്ദുകാരനെയും ഞാൻ കണ്ടെത്തിയില്ല. അവിടുന്ന് പറഞ്ഞു: "നീ പോവുക, ആദ്യം കാണുന്ന ഖുസാഅ് ഗോത്രക്കാരന് ഇത് നൽകുക." അയാൾ പിന്തിരിഞ്ഞുപോയപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അയാളെ വിളിക്കൂ." അയാൾ വന്നപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "ഏറ്റവും പ്രായം ചെന്ന ഖുസാഅ് ഗോത്രക്കാരനെ കണ്ടെത്തി ഇത് അയാൾക്ക് നൽകുക." (ദ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 612, 612, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَاتَ رَجُلٌ مِنْ خُزَاعَةَ، فَأُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمِيرَاثِهِ، فَقَالَ: "الْتَمِسُوا لَهُ وَارِثًا، أَوْ ذَا رَحِمٍ". فَلَمْ يَجِدُوا لَهُ وَارِثًا وَلَا ذَا رَحِمٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَعْطُوهُ الْكُبْرَ مِنْ خُزَاعَةَ". وَفِي رِوَايَةٍ: "انْظُرُوا أَكْبَرَ رَجُلٍ مِنْ خُزَاعَةَ". (د)', 'ബുറൈദ(റ): ഖുസാഅ ഗോത്രത്തിൽപ്പെട്ട ഒരാൾ മരണപ്പെട്ടു. അയാളുടെ അനന്തരസ്വത്ത് നബി(സ)യുടെ അടുത്തേക്ക് കൊണ്ടുവരപ്പെട്ടു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അവന് ഒരു അനന്തരാവകാശിയെ, അല്ലെങ്കിൽ ദൂറഹ്മിനെ (വിഹിതമുള്ളവരോ അസ്വബയോ അല്ലാത്ത കുടുംബം) നിങ്ങൾ അന്വേഷിക്കുക." അവർക്ക് അവന്റെ ഒരു അനന്തരാവകാശിയേയോ ദവുൽ ദൂറഹ്മിനെയോ ലഭിച്ചില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഖുസാഅയിലെ ഏറ്റവും മുതിർന്നവന് അത് നൽകുക." മറ്റൊരു നിവേദനം: "ഖുസാഅയിലെ ഏറ്റവും മുതിർന്നവനെ നിങ്ങൾ അന്വേഷിക്കുക." (ദ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 612, 612, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=9 and h.hadith_no=33), 1, 'وَفِي رِوَايَةٍ: "انْظُرُوا أَكْبَرَ رَجُلٍ مِنْ خُزَاعَةَ". (د)', 'മറ്റൊരു നിവേദനം: "ഖുസാഅയിലെ ഏറ്റവും മുതിർന്നവനെ നിങ്ങൾ അന്വേഷിക്കുക." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَجُلاً مَاتَ وَلَمْ يَدَعْ وَارِثًا إِلَّا غُلَامًا لَهُ كَانَ أَعْتَقَهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ لَهُ أَحَدٌ". قَالُوا: لَا، إِلَّا غُلَامًا لَهُ كَانَ أَعْتَقَهُ. فَجَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِيرَاثَهُ لَهُ. (د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ മരിച്ചു. താൻ മോചിപ്പിച്ച ഒരടിമയല്ലാത്ത ഒരു അനന്തരാവകാശിയും അവനുണ്ടായിരുന്നില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവന് ആരെങ്കിലുമുണ്ടോ?" അവർ പറഞ്ഞു: അവൻ മോചിപ്പിച്ച അടിമയല്ലാതെ ആരും ഇല്ല. അപ്പോൾ റസൂൽ(സ) അയാളുടെ അനന്തരസ്വത്ത് ആ മോചിപ്പിക്കപ്പെട്ട അടിമക്ക് നൽകി. (ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 612, 612, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَرِثُ الْمُسْلِمُ الْكَافِرَ، وَلَا الْكَافِرُ الْمُسْلِمَ". حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'ഉസാമതുബ്നു സൈദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മുസ്ലിം കാഫിറിനെയും, കാഫിർ മുസ്ലിമിനെയും അനന്തരമെടുക്കുകയില്ല." (ബു,മു,ദ,തു,ന,ജ)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 612, 612, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَتَوَارَثُ أَهْلُ مِلَّتَيْنِ شَتَّى". (د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "വ്യത്യസ്തമായ രണ്ട് മതത്തിലെ ആളുകൾ പരസ്പരം അനന്തരമെടുക്കുകയില്ല." (ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 613, 613, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ عَبْدِ اللهِ بْنِ بُرَيْدَةَ: أَنَّ أَخَوَيْنِ اخْتَصَمَا إِلَى يَحْيَى بْنِ يَعْمُر: يَهُودِيٌّ وَمُسْلِمٌ، فَوَرَّثَ الْمُسْلِمَ مِنْهُمَا، وَقَالَ: حَدَّثَنِي أَبُو الأَسْوَدِ: أَنَّ رَجُلًا حَدَّثَهُ: أَنَّ مُعَاذًا حَدَّثَهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْإِسْلَامُ يَزِيدُ وَلَا يَنْقُصُ". فَوَرَّثَ الْمُسْلِمَ. وَفِي رِوَايَةٍ: عَنْ أَبِي الأَسْوَدِ الدِّيلِيِّ: أَنَّ مُعَاذًا أُتِيَ بِمِيرَاثِ يَهُودِيٍّ وَارِثُهُ مُسْلِمٌ،... بِمَعْنَاهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'അബ്ദുല്ലാഹിബ്നു ബുറൈദ(റ): സഹോദരങ്ങളായ ഒരു ജൂതനും മുസ്ലിമും ഒരു തർക്കവുമായി യഹ്യബ്നു യഅ്മുർ(റ)വിന്റെ അടുത്തെത്തി. അപ്പോൾ അദ്ദേഹം അവരിലെ മുസ്ലിമായ വ്യക്തിക്ക് അനന്തരസ്വത്ത് നൽകി. എന്നിട്ടദ്ദേഹം പറഞ്ഞു: മുആദ്(റ) ഒരാൾക്കും അയാൾ അബുൽ അസ്വദ്(റ)വിനും പറഞ്ഞുകൊടുത്ത ഒരു ഹദീസ് അബുൽ അസ്വദ്(റ) എനിക്ക് പറഞ്ഞുതന്നു. മുആദ്(റ) പറയുന്നു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഇസ്ലാം വർധിപ്പിക്കുകയേയുള്ളൂ, ചുരുക്കുകയില്ല." അങ്ങനെ അദ്ദേഹം മുസ്ലിമിന് അനന്തരം നൽകി. മറ്റൊരു നിവേദനം: അബുൽ അസ്വദുദ്ദിയലി(റ) ഇതേ അർത്ഥത്തിലുള്ള ഒരു ഹദീസ് നബി(സ)യിൽ നിന്ന് ഉദ്ധരിക്കുന്നു. അദ്ദേഹം പറയുന്നു: അനന്തരാവകാശി മുസ്ലിമായ ഒരു ജൂതന്റെ അനന്തരസ്വത്ത് മുആദ്(റ)വിന്റെ അടുത്തേക്ക് കൊണ്ടുവരപ്പെട്ടു... (ദ)', 'عَبْدِ اللهِ بْنِ بُرَيْدَةَ', 'അബ്ദുല്ലാഹിബ്നു ബുറൈദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 613, 613, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=9 and h.hadith_no=37), 1, 'وَفِي رِوَايَةٍ: عَنْ أَبِي الأَسْوَدِ الدِّيلِيِّ: أَنَّ مُعَاذًا أُتِيَ بِمِيرَاثِ يَهُودِيٍّ وَارِثُهُ مُسْلِمٌ،... بِمَعْنَاهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'മറ്റൊരു നിവേദനം: അബുൽ അസ്വദുദ്ദിയലി(റ) ഇതേ അർത്ഥത്തിലുള്ള ഒരു ഹദീസ് നബി(സ)യിൽ നിന്ന് ഉദ്ധരിക്കുന്നു. അദ്ദേഹം പറയുന്നു: അനന്തരാവകാശി മുസ്ലിമായ ഒരു ജൂതന്റെ അനന്തരസ്വത്ത് മുആദ്(റ)വിന്റെ അടുത്തേക്ക് കൊണ്ടുവരപ്പെട്ടു... (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُمَا. أَنَّهُ قَالَ: يَا رَسُولَ اللهِ، أَتَنْزِلُ فِي دَارِكَ بِمَكَّةَ؟ قَالَ: "وَهَلْ تَرَكَ لَنَا عَقِيلٌ مِنْ رِبَاعٍ أَوْ دُورٍ". وَكَانَ عَقِيلٌ وَرِثَ أَبَا طَالِبٍ هُوَ وَطَالِبٌ، وَلَمْ يَرِثْ جَعْفَرٌ وَلَا عَلِيٌّ شَيْئًا، لِأَنَّهُمَا كَانَا مُسْلِمَيْنِ، وَكَانَ عَقِيلٌ وَطَالِبٌ كَافِرَيْنِ. فَكَانَ عُمَرُ، مِنْ أَجْلِ ذَلِكَ، يَقُولُ: لَا يَرِثُ الْمُؤْمِنُ الْكَافِرَ. وَقَالَ أُسَامَةُ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَرِثُ الْمُسْلِمُ الْكَافِرَ وَلَا الْكَافِرُ الْمُسْلِمَ". (ق,د,جه)', 'ഉസാമതുബ്നു സൈദ്(റ): അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് മക്കയിലെ അങ്ങയുടെ വീട്ടിലാണോ ഇറങ്ങുന്നത്? തിരുമേനി(സ) പറഞ്ഞു: "അഖീൽ നമുക്ക് വല്ല വീടും ഉപേക്ഷിച്ചിട്ടുണ്ടാകുമോ?" അഖീലും ത്വാലിബും അബൂത്വാലിബിനെ അനന്തരമെടുത്തിരുന്നു. മുസ്ലിംകളായതുകൊണ്ട് അലി(റ)വും ജഅ്ഫർ(റ)വും അബൂത്വാലിബിനെ അനന്തരമെടുത്തില്ല. അഖീലും ത്വാലിബും സത്യനിഷേധികളായിരുന്നു. ഇതുകൊണ്ടുതന്നെ ഉമർ(റ) പറയുമായിരുന്നു: വിശ്വാസി അവിശ്വാസിയെ അനന്തരമെടുക്കുകയില്ല. ഉസാമ(റ) പറയുന്നു: റസൂൽ(സ) പറഞ്ഞു: "മുസ്ലിം കാഫിറിനെയും കാഫിർ മുസ്ലിമിനെയും അനന്തരമെടുക്കുകയില്ല." (ബു,മു,ദ,ജ)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 613, 613, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، أَيْنَ تَنْزِلُ غَدًا؟ فِي حِجَّتِهِ، قَالَ: "وَهَلْ تَرَكَ لَنَا عَقِيلٌ مَنْزِلًا". ثُمَّ قَالَ: "نَحْنُ نَازِلُونَ بِخَيْفِ بَنِي كِنَانَةَ، حَيْثُ تَقَاسَمَتْ قُرَيْشٌ عَلَى الْكُفْرِ". يَعْنِي: الْمُحَصَّبِ، وَذَاكَ أَنَّ بَنِي كِنَانَةَ حَالَفَتْ قُرَيْشًا عَلَى بَنِي هَاشِمٍ: أَنْ لَا يُنَاكِحُوهُمْ، وَلَا يُبَايِعُوهُمْ، وَلَا يُؤْوُوهُمْ. (ق,د,جه)', 'ഉസാമതുബ്നുസൈദ്(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടുന്ന് എവിടെയാണ് നാളെ ഇറങ്ങുന്നത്? ഹജ്ജ് വേളയിലായിരുന്നു അത്. റസൂൽ(സ) പറഞ്ഞു:"അഖീൽ നമുക്ക് വല്ല പാർപിടവും അവശേഷിപ്പിച്ചിട്ടുണ്ടോ?" ശേഷം പറഞ്ഞു: "ബനൂകിനാനക്കാരുടെ ഉയർന്ന പ്രദേശത്താണ് നാം ഇറങ്ങുന്നത്. ഖുറൈശികൾ സത്യനിഷേധത്തിനുമേൽ സത്യംചെയ്ത സ്ഥലത്ത്." മുഹസ്സ്വബ് (ചരൽ പ്രദേശം) ആണ് ഉദ്ദേശം. ബനൂഹാഷിമുകാരോട് വിവാഹബന്ധമോ കച്ചവടമോ നടത്തരുതെന്നും അവർക്ക് അഭയം നൽകരുതെന്നും ബനൂകിനാന ഗോത്രക്കാരുമായി ഖുറൈശികൾ സന്ധിചെയ്തിരുന്നതിനാലാണ് റസൂൽ(സ) അപ്രകാരം പറഞ്ഞത്. (ബു,മു,ദ,ജ)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നുസൈദ്(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 613, 614, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَامَ يَوْمَ فَتْحِ مَكَّةَ فَقَالَ: "الْمَرْأَةُ تَرِثُ مِنْ دِيَةِ زَوْجِهَا وَمَالِهِ، وَهُوَ يَرِثُ مِنْ دِيَتِهَا وَمَالِهَا، مَا لَمْ يَقْتُلْ أَحَدُهُمَا صَاحِبَهُ، فَإِذَا قَتَلَ أَحَدُهُمَا صَاحِبَهُ عَمْدًا لَمْ يَرِثْ مِنْ دِيَتِهِ وَمَالِهِ شَيْئًا، وَإِنْ قَتَلَ أَحَدُهُمَا صَاحِبَهُ خَطَأً وَرِثَ مِنْ مَالِهِ وَلَمْ يَرِثْ مِنْ دِيَتِهِ". [فِي إِسْنَادِهِ مُحَمَّدُ بْنُ سَعِيدُ الْمَصْلُوب، يَضَعُ الْحَدِيثَ] (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): മക്കാവിജയദിനത്തിൽ റസൂൽ(സ) എഴുന്നേറ്റുനിന്നുകൊണ്ട് പറഞ്ഞു: "ഭർത്താവിന്റെ സ്വത്തിൽ നിന്നും നഷ്ടപരിഹാരത്തിൽ നിന്നും സ്ത്രീയും സ്ത്രീയുടെ സ്വത്തിൽ നിന്നും നഷ്ടപരിഹാരത്തിൽ നിന്നും ഭർത്താവും അനന്തരമെടുക്കും. അവരിലൊരാൾ മറ്റെയാളെ വധിക്കാത്ത കാലത്തോളം. മനഃപൂർവ്വം അവരിലൊരാൾ മറ്റെയാളെ വധിച്ചാൽ അവന്റെ സ്വത്തിൽ നിന്നും നഷ്ടപരിഹാരത്തിൽ നിന്നും ഒന്നും തന്നെ ലഭിക്കുകയില്ല. മറ്റെയാളെ അബദ്ധത്തിൽ വധിച്ചാൽ അവന്റെ സ്വത്തിൽ നിന്ന് അനന്തരം ലഭിക്കും, എന്നാൽ നഷ്ടപരിഹാരത്തിൽ നിന്ന് അനന്തരം ലഭിക്കുകയില്ല." ഈ ഹദീസിന്റെ പരമ്പരയിൽ മുഹമ്മദുബ്നു സഈദുൽ മസ്ലൂബ് എന്നയാളുണ്ട്. അദ്ദേഹം ഹദീസ് കെട്ടിച്ചമച്ചുണ്ടാക്കുന്നയാളാണ്. (ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'فِي إِسْنَادِهِ مُحَمَّدُ بْنُ سَعِيدُ الْمَصْلُوب، يَضَعُ الْحَدِيثَ', null, 614, 614, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ مَوْلًى لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَعَ مِنْ عِذْقِ نَخْلَةٍ فَمَاتَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "انْظُرُوا: هَلْ لَهُ مِنْ وَارِثٍ". قَالُوا: لَا، قَالَ: "فَادْفَعُوهُ إِلَى أَهْلِ الْقَرْيَةِ". حَسَنٌ. (د,ت,ن,جه)', 'ആഇശ(റ): നബി(സ)യുടെ ഒരടിമ ഈത്തപ്പനയുടെ മുകളിൽ നിന്ന് വീണുമരണപ്പെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവന് വല്ല അനന്തരാവകാശിയുമുണ്ടോ എന്ന് നിങ്ങൾ നോക്കുക." അവർ പറഞ്ഞു: ഇല്ല. അവിടുന്ന് പറഞ്ഞു: "എങ്കിൽ അത് ഗ്രാമക്കാർക്ക് നൽകുക." (ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 614, 614, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَوْلَى الْقَوْمِ مِنْ أَنْفُسِهِمْ". (خ)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "ഒരു കൂട്ടരുടെ മോചിപ്പിക്കപ്പെട്ട അടിമ അവരിൽ പെട്ടവനാണ്." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 614, 614, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "ابْنُ أُخْتِ الْقَوْمِ مِنْ أَنْفُسِهِمْ". (خ)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "ഒരു സമൂഹത്തിന്റെ സഹോദരീപുത്രൻ അവരിൽ പെട്ടവനാണ്." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 614, 614, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ عَبْدِاللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: تَزَوَّجَ رَبَابُ بْنُ حُذَيْفَةَ بْنِ سَعِيدِ بْنِ سَهْمٍ أُمَّ وَائِلٍ بِنْتَ مَعْمَرٍ الْجُمَحِيَّةَ، فَوَلَدَتْ لَهُ ثَلَاثَةً، فَتُوُفِّيَتْ أُمُّهُمْ، فَوَرِثَهَا بَنُوهَا، رِبَاعًا وَوَلَاءَ مَوَالِيهَا، فَخَرَجَ بِهِمْ عَمْرُو بْنُ الْعَاصِ إِلَى الشَّامِ، فَمَاتُوا فِي طَاعُونِ عَمْوَاسٍ، فَوَرِثَهُمْ عَمْرٌو، وَكَانَ عَصَبَتَهُمْ. فَلَمَّا رَجَعَ عَمْرُو بْنُ الْعَاصِ جَاءَ بَنُو مَعْمَرٍ يُخَاصِمُونَهُ فِي وَلَاءِ أُخْتِهِمْ إِلَى عُمَرَ رَضِيَ اللهُ عَنْهُ، فَقَالَ عُمَرُ رَضِيَ اللهُ عَنْهُ: أَقْضِي بَيْنَكُمْ بِمَا سَمِعْتُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، سَمِعْتُهُ يَقُولُ: "مَا أَحْرَزَ الْوَلَدُ وَالْوَالِدُ فَهُوَ لِعَصَبَتِهِ، مَنْ كَانَ". قَالَ: فَقَضَى لَنَا بِهِ، وَكَتَبَ لَنَا بِهِ كِتَابًا، فِيهِ شَهَادَةُ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ وَزَيْدِ بْنِ ثَابِتٍ وَآخَرَ، حَتَّى إِذَا اسْتُخْلِفَ عَبْدُ الْمَلِكِ بْنُ مَرْوَانَ تُوُفِّيَ مَوْلًى لَهَا وَتَرَكَ أَلْفَيْ دِينَارٍ، فَبَلَغَنِي أَنَّ ذَلِكَ الْقَضَاءَ قَدْ غُيِّرَ، فَخَاصَمُوا إِلَى هِشَامِ بْنِ إِسْمَعِيلَ، فَرَفَعَنَا إِلَى عَبْدِ الْمَلِكِ، فَأَتَيْنَاهُ بِكِتَابِ عُمَرَ رَضِيَ اللهُ عَنْهُ، فَقَالَ: إِنْ كُنْتُ لَأَرَى أَنَّ هَذَا مِنَ الْقَضَاءِ الَّذِي لَا يُشَكُّ فِيهِ، وَمَا كُنْتُ أَرَى أَنَّ أَمْرَ أَهْلِ الْمَدِينَةِ بَلَغَ هَذَا: أَنْ يَشُكُّوا فِي هَذَا الْقَضَاءِ. فَقَضَى لَنَا فِيهِ، فَلَمْ نَزَلْ فِيهِ بَعْدُ. (د,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): മഅ്മറുൽ ജുമഹിയ്യയുടെ മകൾ ഉമ്മുവാഇൽ(റ)യെ റബാബുബിൻ ഹുദൈഫതുബ്നു സഈദുബ്നു സഹ്മ്(റ) വിവാഹം കഴിച്ചു. അദ്ദേഹത്തിൽ നിന്ന് മഹതിക്ക് മൂന്ന് കുട്ടികളുണ്ടായി. അങ്ങനെ അവരുടെ ഉമ്മ മരിച്ചപ്പോൾ മഹതിയുടെ ഭൂസ്വത്തും മഹതി മോചനം നൽകിയ അടിമകളുടെ അനന്തരാവകാശത്തിനുള്ള അവകാശവും അവർക്ക് കിട്ടി. അംറുബ്നു ആസ്(റ) അവരെ ശാമിലേക്ക് കൊണ്ടുപോയി. അമവാസിലെ പ്ലാഗ് ബാധിച്ച് അവർ മരണമടഞ്ഞു. അപ്പോൾ അംറ്(റ) അവരെ അനന്തരമെടുത്തു. അദ്ദേഹം അവരുടെ അസ്വബ (വിഹിതം ക്ലിപ്തപ്പെടുത്തപ്പെട്ടിട്ടില്ലാത്ത, കുടുംബത്തിലെ അടുത്ത ആണുങ്ങൾ)ക്കാരനായിരുന്നു. അംറുബ്നുൽ ആസ്(റ) മടങ്ങിവന്നപ്പോൾ മഅ്മറിന്റെ മക്കൾ, തങ്ങളുടെ സഹോദരിയുടെ മോചനം നൽകപ്പെട്ട അടിമയുടെ അനന്തരാവകാശ വിഷയത്തിൽ, അംറ്(റ)വുമായി തർക്കിച്ചുകൊണ്ട് ഉമർ(റ)വിന്റെ അടുത്തുവന്നു. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ)യിൽ നിന്ന് ഞാൻ കേട്ടതനുസരിച്ച് ഞാൻ നിങ്ങൾക്കിടയിൽ വിധിക്കും. റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "പിതാവിനും മകനും അനന്തരമായി ലഭിക്കുന്നത് അവരുടെ അസ്വബക്കാർക്ക് ലഭിക്കും, അവർ ആരാണെങ്കിലും." നിവേദകൻ പറയുന്നു: അതനുസരിച്ച് ഉമർ(റ) ഞങ്ങൾക്കത് വിധിച്ചു. അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ), സൈദുബ്നു സാബിത്(റ) എന്നിവരുടേയും മറ്റൊരാളുടേയും സാക്ഷ്യം വെച്ച് ഉമർ(റ) ഞങ്ങൾക്കത് എഴുതിത്തന്നു. അബ്ദുൽ മലികുബ്നു മർവാൻ ഭരണാധികാരിയായിരിക്കെ മഹതി മോചിപ്പിച്ച അടിമ മരിച്ചു. രണ്ടായിരം ദീനാറുണ്ടായിരുന്നു അനന്തരസ്വത്ത്. ആ വിധിയിൽ മാറ്റമുണ്ടായി എന്ന് ഞാനറിഞ്ഞു. അപ്പോൾ അവർ ഹിശാമുബ്നു ഇസ്മാഈലിന്റെ അടുത്ത് പരാതിപ്പെട്ടു. ഞങ്ങൾ അബ്ദുൽ മലികിനോട് വിഷയം പറഞ്ഞു: ഉമർ(റ)വിന്റെ എഴുത്തുമായി ഞങ്ങൾ അദ്ദേഹത്തിന്റെ അടുത്തുചെന്നു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഒരിക്കലും സംശയിക്കപ്പെടാത്ത വിധിയാണിതെന്നാണ് ഞാൻ കരുതിയത്. ഈ വിധിയെ സംശയിക്കുന്നിടത്തേക്ക് മദീനക്കാർ എത്തുമെന്ന് ഞാൻ കരുതിയിരുന്നില്ല. അദ്ദേഹം ഞങ്ങൾക്കനുകൂലമായി (ഉമർ(റ)വിന്റെ വിധിപ്രകാരം) വിധിച്ചു. അങ്ങനെ ഞങ്ങളത് കൈവശം വെച്ചു. (ദ,ജ)', 'عَبْدِاللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 615, 615, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ مَوْلًى لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَعَ مِنْ نَخْلَةٍ فَمَاتَ، وَتَرَكَ مَالًا، وَلَمْ يَتْرُكْ وَلَدًا وَلَا حَمِيمًا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَعْطُوا مِيرَاثَهُ رَجُلًا مِنْ أَهْلِ قَرْيَتِهِ". (د,ت,جه)', 'ആഇശ(റ): നബി(സ)യുടെ മോചനം നൽകപ്പെട്ട അടിമ ഈത്തപ്പനയിൽ നിന്ന് വീണ് മരണപ്പെട്ടു. അയാളുടെ കുറച്ച് സ്വത്ത് അനന്തരമായുണ്ടായിരുന്നു. എന്നാൽ മക്കളോ അടുത്ത ബന്ധുക്കളോ ഉണ്ടായിരുന്നില്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അയാളുടെ അനന്തരസ്വത്ത് അയാളുടെ ഗ്രാമക്കാരനായ ഒരാൾക്ക് നൽകുക." (ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 615, 616, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ بِنْتِ حَمْزَةَ بْنِ عَبْدِ الْمُطَّلِبِ رَضِيَ اللهُ عَنْهُمَا قَالَتْ: مَاتَ مَوْلَايَ وَتَرَكَ ابْنَةً، فَقَسَمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَالَهُ بَيْنِي وَبَيْنَ ابْنَتِهِ، فَجَعَلَ لِيَ النِّصْفَ وَلَهَا النِّصْفَ. (جه)', 'ബിൻതുഹംസതിബ്നി അബ്ദിൽ മുത്വലിബ്(റ): എന്റെ മോചിപ്പിക്കപ്പെട്ട അടിമ മരണപ്പെട്ടു. അയാൾക്ക് ഒരു മകളുണ്ടായിരുന്നു. റസൂൽ(സ) അയാളുടെ സമ്പത്ത് എനിക്കും അയാളുടെ പുത്രിക്കും വീതിച്ചു നൽകി. എനിക്കും പകുതി, അവൾക്കും പകുതി. (ജ)', 'بِنْتِ حَمْزَةَ بْنِ عَبْدِ الْمُطَّلِبِ', 'ബിൻതുഹംസതിബ്നി അബ്ദിൽ മുത്വലിബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 616, 616, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ عَبْدِالله بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَرِثُ الْوَلَاءَ مَنْ يَرِثُ الْمَالَ". (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "സ്വത്ത് അനന്തരമെടുക്കുന്നവർ മോചനം നൽകപ്പെട്ട അടിമയുടെ സ്വത്തും അനന്തരമെടുക്കും." (തു)', 'عَبْدِالله بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 616, 616, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا أَرَادَتْ أَنْ تَشْتَرِيَ بَرِيرَةَ رَضِيَ اللهُ عَنْهَا، فَاشْتَرَطُوا الْوَلَاءَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْوَلَاءُ لِمَنْ أَعْطَى الثَّمَنَ أَوْ لِمَنْ وَلِيَ النِّعْمَةَ". (ق,د,ت,ن,جه)', 'ആഇശ(റ): മഹതി ബരീറ(റ)യെ വാങ്ങാൻ ഉദ്ദേശിച്ചു. അപ്പോൾ അവർ (ആദ്യ ഉടമകൾ) ബരീറ(റ)യുടെ അനന്തരാവകാശം തങ്ങൾക്കായിരിക്കണമെന്ന് ഉപാധിവെച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "വില നൽകിയവന്നാണ് അല്ലെങ്കിൽ അനുഗ്രഹത്തെ ഉടമപ്പെടുത്തുന്നവന്നാണ്, മോചിപ്പിക്കപ്പെട്ട അടിമയുടെ അനന്തരാവകാശം." (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 616, 616, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَرَادَتْ أَنْ تَشْتَرِيَ جَارِيَةً تُعْتِقُهَا، فَقَالَ أَهْلُهَا: نَبِيعُكِهَا عَلَى أَنَّ وَلَاءَهَا لَنَا. فَذَكَرَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا ذَاكَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "لَا يَمْنَعُكِ ذَلِكِ، فَإِنَّ الْوَلَاءَ لِمَنْ أَعْتَقَ". (ق,د,ن)', 'ഇബ്നുഉമർ(റ): മോചനം നൽകാൻ വേണ്ടി ഒരടിമസ്ത്രീയെ വാങ്ങാൻ ആഇശ(റ) ഉദ്ദേശിച്ചു. അടിമസ്ത്രീയുടെ ആളുകൾ പറഞ്ഞു: അവളെ ഞങ്ങൾ നിങ്ങൾക്ക് വിൽക്കും. പക്ഷേ, അവളുടെ അനന്തരാവകാശം ഞങ്ങൾക്കായിരിക്കും. ആഇശ(റ) ഇത് നബി(സ)യോട് പറഞ്ഞു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അത് നിന്നെ തടയരുത്. സ്വതന്ത്രനാക്കിയവനാണ് അനന്തരാവകാശത്തിന് അവകാശി." (ബു,മു,ദ,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 616, 616, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ الْوَلَاءِ، وَعَنْ هِبَتِهِ. (ق,د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): മോചനം നൽകപ്പെട്ട അടിമയുടെ അനന്തരാവകാശത്തിനുള്ള അവകാശം വിൽക്കലും ദാനം നൽകലും റസൂൽ(സ) വിലക്കിയിരിക്കുന്നു. (ബു,മു,ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 616, 616, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ يَزِيدَ بْنِ شَرِيكٍ التَّيْمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: خَطَبَنَا عَلِيٌّ رَضِيَ اللهُ عَنْهُ فَقَالَ: مَنْ زَعَمَ أَنَّ عِنْدَنَا شَيْئًا نَقْرَؤُهُ إِلَّا كِتَابَ اللهِ وَهَذِهِ الصَّحِيفَةَ – صَحِيفَةٌ فِيهَا أَسْنَانُ الإِبِلِ، وَأَشْيَاءُ مِنَ الْجِرَاحَاتِ – فَقَدْ كَذَبَ. قَالَ: وَفِيهَا: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْمَدِينَةُ حَرَامٌ مَا بَيْنَ عَيْرٍ إِلَى ثَوْرٍ، فَمَنْ أَحْدَثَ فِيهَا حَدَثًا أَوْ آوَى مُحْدِثًا فَعَلَيْهِ لَعْنَةُ اللهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ، لَا يَقْبَلُ اللهُ مِنْهُ يَوْمَ الْقِيَامَةِ صَرْفًا وَلَا عَدْلًا. وَمَنِ ادَّعَى إِلَى غَيْرِ أَبِيهِ – أَوْ تَوَلَّى غَيْرَ مَوَالِيهِ – فَعَلَيْهِ لَعْنَةُ اللهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ، لَا يُقْبَلُ مِنْهُ صَرْفٌ وَلَا عَدْلٌ. وَذِمَّةُ الْمُسْلِمِينَ وَاحِدَةٌ، يَسْعَى بِهَا أَدْنَاهُمْ". حَسَنٌ صَحِيحٌ. (ق,د,ت,ن)', 'യസീദുബ്നു ശരീക്(റ): പ്രഭാഷണം നടത്തിക്കൊണ്ടിരിക്കെ അലി(റ) പറഞ്ഞു: ഈ ഏടും - ഒട്ടകങ്ങളുടെ പ്രായത്തെക്കുറിച്ചും മുറിവ് പറ്റിയാലുള്ള ചില വിധികളെക്കുറിച്ചുമാണ് ആ ഏടിലുള്ളത് - അല്ലാഹുവിന്റെ ഗ്രന്ഥവുമല്ലാത്ത, നാം പാരായണം ചെയ്യുന്ന ഒന്ന് നമ്മുടെ പക്കലുണ്ടെന്ന് ആരെങ്കിലും പറഞ്ഞാൽ അവൻ കളവാണ് പറഞ്ഞത്. നിവേദകൻ പറയുന്നു: ആ ഏടിൽ ഇപ്രകാരമുണ്ടായിരുന്നു: റസൂൽ(സ) പറഞ്ഞു: "മദീന, ഐറ് മുതൽ സൗറ് വരെ പവിത്രമാണ്. അതിൽ ആരെങ്കിലും പുതുതായി ഉണ്ടാക്കിയാൽ, അല്ലെങ്കിൽ പുതുതായി ഉണ്ടാക്കുന്നവന് അഭയം നൽകിയാൽ അവന്റെ മേൽ അല്ലാഹുവിന്റെയും മാലാഖമാരുടെയും മുഴുജനങ്ങളുടെയും ശാപമുണ്ടാകും. അന്ത്യദിനത്തിൽ അവനിൽ നിന്ന് അല്ലാഹു നിർബന്ധമോ സുന്നത്തോ ആയ ഒരു കർമങ്ങളും സ്വീകരിക്കുന്നതല്ല. വല്ലവനും തന്റെ പിതാവല്ലാത്തവന്റെ മേൽ പിതൃത്വം ആരോപിച്ചാൽ - അല്ലെങ്കിൽ തനിക്ക് അടിമത്വത്തിൽ നിന്ന് മോചനം നൽകിയവനല്ലാത്ത ഒരാളെ അയാളാണ് തന്നെ മോചിപ്പിച്ചതെന്ന് പറഞ്ഞാൽ - അവന്റെ മേൽ അല്ലാഹുവിന്റെയും മാലാഖമാരുടെയും മുഴുജനങ്ങളുടെയും ശാപമുണ്ടാകും. അവന്റെ സുന്നത്തും നിർബന്ധവുമായ ഒരു കർമ്മവും സ്വീകരിക്കപ്പെടുന്നതല്ല. മുസ്ലിംകളുടെ കരാർ ഏകമാണ്. അവരിലെ ഏറ്റവും താഴ്ന്നവരും അത് ഏറ്റെടുക്കും." (ബു,മു,ദ,തു,ന)', 'يَزِيدَ بْنِ شَرِيكٍ التَّيْمِيِّ', 'യസീദുബ്നു ശരീക്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 617, 617, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنِ ادَّعَى إِلَى غَيْرِ أَبِيهِ وَهُوَ يَعْلَمُ أَنَّهُ غَيْرُ أَبِيهِ فَالْجَنَّةُ عَلَيْهِ حَرَامٌ". فَذُكِرَ ذَلِكَ لِأَبِي بَكْرَةَ، فَقَالَ: وَأَنَا سَمِعَتْهُ أُذُنَايَ، وَوَعَاهُ قَلْبِي مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "തന്റെ പിതാവല്ലെന്നറിഞ്ഞിട്ടും തന്റെ പിതാവല്ലാത്ത ഒരാളുടെമേൽ തന്റെ പിതൃത്വം ആരോപിച്ചവന് സ്വർഗ്ഗം നിഷിദ്ധമാണ്." ഇതേക്കുറിച്ച് അബൂബക്റ(റ)വിനോട് പറയപ്പെട്ടു: അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ)യിൽ നിന്ന് എന്റെ ഇരു ചെവികൾ കൊണ്ടും ഞാനത് കേട്ടിട്ടുണ്ട്, എന്റെ ഹൃദയം മനഃപാഠമാക്കിയിട്ടുമുണ്ട്. (ബു)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 617, 617, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَرْغَبُوا عَنْ آبَائِكُمْ فَمَنْ رَغِبَ عَنْ أَبِيهِ فَقَدْ كَفَرَ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ പിതാക്കളെ നിങ്ങൾ വെറുക്കരുത്. തന്റെ പിതാവിനെ വെറുക്കുന്നവൻ നന്ദികെട്ടവനത്രെ." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 617, 617, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ وَاثِلَةَ بْنِ الأَسْقَعِ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمَرْأَةُ تَحْرِزُ ثَلَاثَةَ مَوَارِيثَ: عَتِيقَهَا، وَلَقِيطَهَا، وَوَلَدَهَا الَّذِي لَاعَنَتْ عَنْهُ".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=9 and h.hadith_no=54), 1, 'وَفِي رِوَايَةٍ: عَنْ عَبْدِاللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، مِثْلَهُ.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا نَزَلَتْ آيَةُ اللِّعَانِ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَيُّمَا امْرَأَةٍ أَلْحَقَتْ بِقَوْمٍ مَنْ لَيْسَ مِنْهُمْ فَلَيْسَتْ مِنَ اللهِ فِي شَيْءٍ، وَلَنْ يُدْخِلَهَا جَنَّتَهُ. وَأَيُّمَا رَجُلٍ أَنْكَرَ وَلَدَهُ، وَقَدْ عَرَفَهُ، احْتَجَبَ اللهُ مِنْهُ يَوْمَ الْقِيَامَةِ، وَفَضَحَهُ عَلَى رُءُوسِ الأَشْهَادِ". [فِي سَنَدِهِ مَجْهُولٌ] (جه)', 'അബൂഹുറൈറ(റ): ലിആന്റെ സൂക്തമിറങ്ങിയപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഒരു സമൂഹത്തിലേക്ക് അവരിൽ പെടാത്തവരെ (തന്റെ മകനെ) ചേർക്കുന്ന സ്ത്രീയുമായി അല്ലാഹുവിന് ഒരു ബന്ധവുമുണ്ടാവില്ല. അല്ലാഹു അവളെ തന്റെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുകയുമില്ല. അറിഞ്ഞിട്ടും തന്റെ മകനെ നിഷേധിക്കുന്നവനിൽ നിന്ന് അന്ത്യനാളിൽ അല്ലാഹു മറഞ്ഞുനിൽക്കും. സാക്ഷികളുടെ മുന്നിൽവെച്ച് അവനെ വഷളാക്കുകയും ചെയ്യും." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'فِي سَنَدِهِ مَجْهُولٌ', null, 618, 618, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كُفْرٌ بِامْرِئٍ ادِّعَاءُ نَسَبٍ لَا يَعْرِفُهُ، أَوْ جَحْدُهُ، وَإِنْ دَقَّ". (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "ഒരു വ്യക്തി, തനിക്കറിയാത്ത ഒരു കുടുംബബന്ധത്തെക്കുറിച്ച്, അത് എത്ര നിസാരമാണെങ്കിലും ശരി, അത് ഉണ്ടെന്ന് വാദിക്കലും, അല്ലെങ്കിൽ അത് നിഷേധിക്കലും അവനിലെ സത്യനിഷേധമാണ്." (ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 618, 618, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ عَاهَرَ أَمَةً أَوْ حُرَّةً فَوَلَدُهُ وَلَدُ زِنًا، لَا يَرِثُ وَلَا يُورَثُ". (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു അടിമസ്ത്രീയേയോ, സ്വതന്ത്രയേയോ വ്യഭിചരിച്ചുണ്ടായ കുട്ടി ജാരസന്താനമാണ്. അവൻ അനന്തരമെടുക്കുകയോ അനന്തരമെടുക്കപ്പെടുകയോ ഇല്ല." (ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 618, 619, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كُلُّ مُسْتَلْحَقٍ اسْتُلْحِقَ بَعْدَ أَبِيهِ الَّذِي يُدْعَى لَهُ، ادَّعَاهُ وَرَثَتُهُ مِنْ بَعْدِهِ، فَقَضَى أَنَّ مَنْ كَانَ مِنْ أَمَةٍ يَمْلِكُهَا يَوْمَ أَصَابَهَا، فَقَدْ لَحِقَ بِمَنِ اسْتَلْحَقَهُ. وَلَيْسَ لَهُ فِيمَا قُسِمَ قَبْلَهُ مِنَ الْمِيرَاثِ شَيْءٌ، وَمَا أُدْرِكَ مِنْ مِيرَاثٍ لَمْ يُقْسَمْ فَلَهُ نَصِيبُهُ. وَلَا يُلْحَقُ إِذَا كَانَ أَبُوهُ الَّذِي يُدْعَى لَهُ أَنْكَرَهُ، وَإِنْ كَانَ مِنْ أَمَةٍ لَا يَمْلِكُهَا، أَوْ مِنْ حُرَّةٍ عَاهَرَ بِهَا، فَإِنَّهُ لَا يُلْحَقُ وَلَا يُورَثُ. وَإِنْ كَانَ الَّذِي يُدْعَى لَهُ هُوَ ادَّعَاهُ فَهُوَ وَلَدُ زِنًا، لِأَهْلِ أُمِّهِ مَنْ كَانُوا، حُرَّةً أَوْ أَمَةً". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "തന്റെ പിതാവെന്ന് അറിയപ്പെടുന്ന വ്യക്തിയുടെ മരണ ശേഷം അയാളുടെ അനന്തരാവകാശികൾ ഇവനെ അയാളുടെ മകനാണെന്ന് പറഞ്ഞാൽ, അയാൾ ബന്ധപ്പെടുമ്പോൾ തന്റെ ഉടമസ്ഥതയിലുണ്ടായിരുന്ന അടിമസ്ത്രീയുടെ മകനാണ് അവനെങ്കിൽ അവൻ അവരുടെ കൂടെ ചേരുന്നതാണ്. ഇതിന് മുമ്പ് വീതിക്കപ്പെട്ട അനന്തരസ്വത്തിൽ നിന്ന് അവന് ഒന്നും തന്നെ ലഭിക്കുകയുമില്ല. എന്നാൽ ഇതുവരെ വീതിക്കപ്പെടാത്ത അനന്തരസ്വത്തിൽനിന്ന് അവന്റെ വിഹിതം അവന് ലഭിക്കുന്നതാണ്. തന്റെ പിതാവെന്നറിയപ്പെടുന്ന വ്യക്തി അവനെ നിരാകരിച്ചാൽ അവൻ ആ കുടുംബവുമായി ചേരുന്നതല്ല. അയാളുടെ ഉടമസ്ഥതയിലില്ലാതിരുന്ന അടിമസ്ത്രീയിലാണ് അവൻ ജനിച്ചതെങ്കിൽ, അല്ലെങ്കിൽ സ്വതന്ത്രയായ സ്ത്രീയെ വ്യഭിചരിച്ചുണ്ടായതാണെങ്കിൽ അവൻ അയാളുടെ കുടുംബവുമായി ചേരുകയോ അവനെ അനന്തരമെടുക്കപ്പെടുകയോ ഇല്ല. അവന്റെ പിതാവെന്നറിയപ്പെടുന്ന വ്യക്തി അവൻ തന്റെ മകനാണെന്ന് അവകാശപ്പെട്ടാലും അവൻ ജാരസന്തതിയാണ്. അവൻ തന്റെ മാതാവിന്റെ, അവൾ സ്വതന്ത്രയാണെങ്കിലും അടിമയാണെങ്കിലും, കുടുംബത്തോടൊപ്പം ആയിരിക്കും; അവർ ആരായിരുന്നാലും ശരി." (ദ,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 619, 619, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كُلُّ قَسْمٍ قُسِمَ فِي الْجَاهِلِيَّةِ فَهُوَ عَلَى مَا قُسِمَ لَهُ، وَكُلُّ قَسْمٍ أَدْرَكَهُ الإِسْلَامُ فَهُوَ عَلَى قَسْمِ الإِسْلَامِ". (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "അജ്ഞാനകാലത്ത് വിഹിതം വെക്കപ്പെട്ടത് അന്നത്തെ നിയമ പ്രകാരമായിരിക്കും. എന്നാൽ ഇസ്ലാം വന്നതിന് ശേഷമുള്ള അനന്തര സ്വത്തുക്കൾ വീതിക്കപ്പെടേണ്ടത് ഇസ്ലാമിക നിയമ പ്രകാരമാണ്." (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 619, 619, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا اسْتَهَلَّ الصَّبِيُّ صُلِّيَ عَلَيْهِ، وَوُرِّثَ". (جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "കുട്ടി ശബ്ദമുണ്ടാക്കിയാൽ (ജനിച്ചയുടനെ, അപ്പോൾ തന്നെ മരിക്കുകയും ചെയ്തു) അവന്റെ മേൽ നിസ്കരിക്കേണ്ടതാണ്. അവന് അനന്തരവിഹിതം ലഭിക്കുന്നതാണ്." (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 619, 619, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ وَالْمِسْوَرِ بْنِ مَخْرَمَةَ – رَضِيَ اللهُ عَنْهُمْ – قَالَا: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَرِثُ الصَّبِيُّ حَتَّى يَسْتَهِلَّ صَارِخًا". (جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ), മിസ്വർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഉച്ചത്തിൽ കരയാത്ത (ജനിച്ചയുടനെ) കുട്ടിക്ക് അനന്തര വിഹിതം ലഭിക്കുന്നതല്ല." (ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ وَالْمِسْوَرِ بْنِ مَخْرَمَةَ –', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 620, 620, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ تَمِيمِ الدَّارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، مَا السُّنَّةُ فِي الرَّجُلِ مِنْ أَهْلِ الْكِتَابِ يُسْلِمُ عَلَى يَدَيِ الرَّجُلِ؟ قَالَ: "هُوَ أَوْلَى النَّاسِ بِمَحْيَاهُ وَمَمَاتِهِ". (د,ت,جه)', 'തമീമുദ്ദാരി(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഒരാളുടെ കരങ്ങളാൽ മുസ്ലിമാകുന്ന വേദക്കാരന്റെ ചര്യയെന്താണ്? അവിടന്ന് പറഞ്ഞു: "തന്റെ ജീവിതത്തിലും മരണാനന്തരവും അവനോട് (ഇസ്ലാമിലേക്ക് കൊണ്ട് വന്നവനോട്) ജനങ്ങളിൽ വെച്ച് ഏറ്റവും അടുത്തവനാണവൻ." (ദ,തു,ജ)', 'تَمِيمِ الدَّارِيِّ', 'തമീമുദ്ദാരി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 620, 620, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَضَى فِي جَنِينِ امْرَأَةٍ مِنْ بَنِي لِحْيَانَ سَقَطَ مَيِّتًا بِغُرَّةٍ: عَبْدٍ أَوْ أَمَةٍ. ثُمَّ إِنَّ الْمَرْأَةَ الَّتِي قُضِيَ عَلَيْهَا بِالْغُرَّةِ تُوُفِّيَتْ، فَقَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّ مِيرَاثَهَا لِبَنِيهَا وَزَوْجِهَا، وَأَنَّ عَقْلَهَا عَلَى عَصَبَتِهَا. (ق,د,ت,ن)', 'അബൂഹുറൈറ(റ): ബനൂലഹ്യാനിലെ ഒരു സ്ത്രീയുടെ മരിച്ചുവീണ ഗർഭസ്ഥ ശിശുവിന് നഷ്ട പരിഹാരമായി ഒരു അടിമയേയോ അടിമസ്ത്രീയേയോ നൽകണമെന്ന് റസൂൽ(സ) വിധിച്ചു. ശേഷം നഷ്ടപരിഹാരം നൽകേണ്ട സ്ത്രീ മരണപ്പെട്ടു. അപ്പോൾ അവിടന്ന് വിധിച്ചു: അവളുടെ അനന്തരസ്വത്ത് അവളുടെ ഭർത്താവിനും മക്കൾക്കുമാണ്. എന്നാൽ അവളുടെ അസ്വബക്കാരാണ് (വിഹിതം നിശ്ചയിക്കപ്പെട്ടിട്ടില്ലാത്ത അടുത്ത പുരുഷന്മാരാണ്) നഷ്ടപരിഹാരം നൽകേണ്ടത്. (ബു,മു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 620, 620, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: {وَالَّذِينَ عَاقَدَتْ أَيْمَانُكُمْ فَآتُوهُمْ نَصِيبَهُمْ} [النّساء: ٣٣]. كَانَ الرَّجُلُ يُحَالِفُ الرَّجُلَ، لَيْسَ بَيْنَهُمَا نَسَبٌ، فَيَرِثُ أَحَدُهُمَا الآخَرَ، فَنَسَخَ ذَلِكَ الأَنْفَالُ، فَقَالَ تَعَالَى: {وَأُولُو الأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ} [الأنفال: ٧٥]. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''നിങ്ങളുടെ വലതുകരങ്ങൾ ബന്ധം സ്ഥാപിച്ചിട്ടുള്ളവർക്കും അവരുടെ വിഹിതം നിങ്ങൾ നൽകുക.'' (നിസാഅ്: 33) ബന്ധുക്കളല്ലാത്ത രണ്ടുപേർ കരാർ ചെയ്ത് ബന്ധം സ്ഥാപിക്കുകയും, അങ്ങനെ ഒരുവൻ മറ്റെയാളുടെ അനന്തരസ്വത്തിന് അർഹനാവുകയും ചെയ്യുമായിരുന്നു. എന്നാൽ മേൽസൂക്തത്തെ അൻഫാലിലെ സൂക്തം ദുർബ്ബലപ്പെടുത്തി. അല്ലാഹു പറയുന്നു: ''എന്നാൽ രക്തബന്ധമുള്ളവർ പരസ്പരം കൂടുതൽ ബന്ധപ്പെട്ടവരാകുന്നു.'' (അൻഫാൽ: 75) (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'الأنفال: ٧٥', null, 620, 621, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: فِي قَوْلِهِ تَعَالَى: {وَالَّذِينَ عَاقَدَتْ أَيْمَانُكُمْ فَآتُوهُمْ نَصِيبَهُمْ} قَالَ: كَانَ الْمُهَاجِرُونَ حِينَ قَدِمُوا الْمَدِينَةَ تُورَّثُ الأَنْصَارُ دُونَ ذَوِي رَحِمِهِ، لِلأُخُوَّةِ الَّتِي آخَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَهُمْ، فَلَمَّا نَزَلَتْ هَذِهِ الآيَةُ: {وَلِكُلٍّ جَعَلْنَا مَوَالِيَ مِمَّا تَرَكَ} [النّساء: ٣٣] قَالَ: نَسَخَتْهَا: {وَالَّذِينَ عَقَدَتْ أَيْمَانُكُمْ فَآتُوهُمْ نَصِيبَهُمْ} مِنَ النَّصْرِ وَالنَّصِيحَةِ وَالرِّفَادَةِ، وَيُوصِي لَهُ، وَقَدْ ذَهَبَ الْمِيرَاثُ. (خ,د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''നിങ്ങളുടെ വലതുകരങ്ങൾ ബന്ധം സ്ഥാപിച്ചിട്ടുള്ളവർക്കും അവരുടെ വിഹിതം നൽകുക.'' എന്ന സൂക്തത്തെ കുറിച്ച് അദ്ദേഹം പറയുന്നു: മുഹാജിറുകൾ മദീനയിൽ വന്നപ്പോൾ, റസൂൽ(സ) അവർക്കിടയിൽ ഉണ്ടാക്കിയ സഹോദര ബന്ധത്തിന്റെ പേരിൽ രക്തബന്ധമില്ലാതെ തന്നെ, അൻസാറുകളിൽ നിന്ന് അനന്തരമെടുത്തിരുന്നു. ''ഏതൊരാൾക്കും തന്റെ മാതാപിതാക്കളും അടുത്ത ബന്ധുക്കളും വിട്ടേച്ചുപോയ സ്വത്തിന് നാം അവകാശികളെ നിശ്ചയിച്ചിട്ടുണ്ട്.'' (നിസാഅ്: 33) എന്ന സൂക്തം ഇറങ്ങിയപ്പോൾ ''നിങ്ങളുടെ വലതുകരങ്ങൾ ബന്ധം സ്ഥാപിച്ചവർക്ക് അവരുടെ വിഹിതം നിങ്ങൾ നൽകുക.'' എന്ന സൂക്തത്തെ അത് ദുർബലപ്പെടുത്തി. ഈ ബന്ധം സ്ഥാപിച്ചിരുന്നത് സഹായം, സഹകരണം, ഉപദേശം എന്നിവക്ക് വേണ്ടിയായിരുന്നു. അവർക്ക് വേണ്ടി വസ്വിയ്യത് ചെയ്യാം. എന്നാൽ അവർക്ക് അനന്തരവിഹിതം നിരോധിച്ചിട്ടുണ്ട്. (ബു,ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], 'النّساء: ٣٣', null, 621, 621, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ دَاوُدَ بْنِ الْحُصَيْنِ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ أَقْرَأُ عَلَى أُمِّ سَعْدٍ بِنْتِ الرَّبِيعِ، وَكَانَتْ يَتِيمَةً فِي حِجْرِ أَبِي بَكْرٍ، فَقَرَأْتُ: {وَالَّذِينَ عَقَدَتْ أَيْمَانُكُمْ} فَقَالَتْ: لَا تَقْرَأْ: {وَالَّذِينَ عَقَدَتْ أَيْمَانُكُمْ} إِنَّمَا نَزَلَتْ فِي أَبِي بَكْرٍ وَابْنِهِ عَبْدِ الرَّحْمَنِ حِينَ أَبَى الإِسْلَامَ، فَحَلَفَ أَبُو بَكْرٍ أَلَّا يُورِّثَهُ، فَلَمَّا أَسْلَمَ أَمَرَ اللهُ تَعَالَى نَبِيَّهُ عَلَيْهِ السَّلَامُ أَنْ يُؤْتِيَهُ نَصِيبَهُ، فَمَا أَسْلَمَ حَتَّى حُمِلَ عَلَى الإِسْلَامِ بِالسَّيْفِ. (د)', 'ദാവൂദുബ്നു ഹുസൈ്വൻ(റ): റബീഇന്റെ പുത്രി ഉമ്മുസഅ്ദ്(റ)വിന് ഞാൻ ഖുർആൻ ഓതിക്കേൾപിക്കുമായിരുന്നു. അബൂബക്കർ(റ)വിന്റെ സംരക്ഷണത്തിൽ ജീവിക്കുന്ന അനാഥയായിരുന്നു അവർ. ''നിങ്ങളുടെ വലതുകരങ്ങൾ ബന്ധം സ്ഥാപിച്ചവർ'' എന്ന് ഞാൻ ഓതി. അപ്പോൾ അവർ പറഞ്ഞു: ''നിങ്ങളുടെ വലതുകരങ്ങൾ ബന്ധം സ്ഥാപിച്ചിട്ടുള്ളവർ'' എന്ന് നീ ഓതരുത്. അത് അബൂബക്കർ(റ)വിന്റെയും മകൻ അബ്ദുർറഹ്മാന്റെയും വിഷയത്തിൽ ഇറങ്ങിയതാണ്. അബ്ദുറഹ്മാൻ(റ) ഇസ്ലാം സ്വീകരിക്കാൻ വിസമ്മതിച്ചു. അപ്പോൾ അദ്ദേഹത്തിന് അനന്തരസ്വത്ത് കൊടുക്കില്ലെന്ന് അബൂബക്കർ(റ) സത്യം ചെയ്തു. അദ്ദേഹം ഇസ്ലാം സ്വീകരിച്ചപ്പോൾ അല്ലാഹു റസൂൽ(സ)യോട് അദ്ദേഹത്തിന്റെ വിഹിതം നൽകാൻ കൽപിച്ചു. വാളുകൊണ്ട് ഇസ്ലാം സ്വീകരിക്കാൻ നിർബന്ധിക്കപ്പെടുന്നത് വരെ അദ്ദേഹം ഇസ്ലാം സ്വീകരിച്ചിരുന്നില്ല. (ദ)', 'دَاوُدَ بْنِ الْحُصَيْنِ', 'ദാവൂദുബ്നു ഹുസൈ്വൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 621, 621, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: {وَالَّذِينَ آمَنُوا وَهَاجَرُوا ..... وَالَّذِينَ آمَنُوا وَلَمْ يُهَاجِرُوا} فَكَانَ الأَعْرَابِيُّ لَا يَرِثُ الْمُهَاجِرَ وَلَا يَرِثُهُ الْمُهَاجِرُ، فَنَسَخَتْهَا، فَقَالَ تَعَالَى: {وَأُولُو الأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ} [الأنفال: ٧٥]. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''വിശ്വസിക്കുകയും ഹിജ്റ പോകുകയും ചെയ്തവർ..... വിശ്വസിക്കുകയും എന്നാൽ ഹിജ്റ പോകാതിരിക്കുകയും ചെയ്തവർ'' എന്ന സൂക്തത്തെക്കുറിച്ച് അദ്ദേഹം പറയുന്നു: അഅ്റാബികൾ മുഹാജിറുകളെയോ മുഹാജിറുകൾ അഅ്റാബികളെയോ അനന്തരമെടുക്കുമായിരുന്നില്ല. എന്നാൽ ഇതിനെ ദുർബലപ്പെടുത്തിക്കൊണ്ട് അല്ലാഹു പറഞ്ഞു: ''രക്തബന്ധമുള്ളവർ പരസ്പരം കൂടുതൽ ബന്ധപ്പെട്ടവരാകുന്നു.'' (അൻഫാൽ: 75) (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'الأنفال: ٧٥', null, 621, 621, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا حِلْفَ فِي الإِسْلَامِ، وَأَيُّمَا حِلْفٍ كَانَ فِي الْجَاهِلِيَّةِ لَمْ يَزِدْهُ الإِسْلَامُ إِلَّا شِدَّةً". (م,د)', 'ജുബൈറുബ്നു മുത്ഇം(റ): റസൂൽ(സ) പറഞ്ഞു: "ഇസ്ലാമിൽ സന്ധി (ജാഹിലിയ്യാ കാലത്തുണ്ടായിരുന്ന അന്യായമായ ഉടമ്പടികൾ) ഇല്ല. ജാഹിലിയ്യാ കാലത്ത് ഏതെങ്കിലും സന്ധി (ന്യായമായ സന്ധി) ഉണ്ടായിരുന്നുവെങ്കിൽ ഇസ്ലാം അതിന് കൂടുതൽ ശക്തി നൽകുന്നേയുള്ളൂ." (മു,ദ)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈറുബ്നു മുത്ഇം(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 622, 622, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: حَالَفَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ الْمُهَاجِرِينَ وَالأَنْصَارِ فِي دَارِنَا، فَقِيلَ لَهُ: أَلَيْسَ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا حِلْفَ فِي الإِسْلَامِ". فَقَالَ: حَالَفَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ الْمُهَاجِرِينَ وَالأَنْصَارِ فِي دَارِنَا، مَرَّتَيْنِ أَوْ ثَلَاثًا. (ق,د)', 'അനസുബ്നു മാലിക്(റ): ഞങ്ങളുടെ വീട്ടിൽ വെച്ച് മുഹാജിറുകൾക്കും അൻസാറുകൾക്കും ഇടയിൽ റസൂൽ(സ) സന്ധി ചെയ്യിച്ചു (സാഹോദര്യമുണ്ടാക്കി). അപ്പോൾ അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: "ഇസ്ലാമിൽ സന്ധിയില്ല" എന്ന് റസൂൽ(സ) പറഞ്ഞിട്ടില്ലേ? അദ്ദേഹം പറഞ്ഞു: മുഹാജിറുകൾക്കും അൻസാറുകൾക്കുമിടയിൽ  റസൂൽ(സ) ഞങ്ങളുടെ വീട്ടിൽ വെച്ച് സന്ധി ചെയ്യിച്ചു. രണ്ടോ മൂന്നോ പ്രാവശ്യം അദ്ദേഹമത് ആവർത്തിച്ചു. (ബു,മു,ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 622, 622, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: الدِّيَةُ لِلْعَاقِلَةِ، وَلَا تَرِثُ الْمَرْأَةُ مِنْ دِيَةِ زَوْجِهَا شَيْئًا، حَتَّى قَالَ لَهُ الضَّحَّاكُ بْنُ سُفْيَانَ: – وَفِي رِوَايَةٍ: وَكَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اسْتَعْمَلَهُ عَلَى الأَعْرَابِ – كَتَبَ إِلَيَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ أُوَرِّثَ امْرَأَةَ أَشْيَمَ الضِّبَابِيِّ مِنْ دِيَةِ زَوْجِهَا، فَرَجَعَ عُمَرُ. (د,ت,جه)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): അദ്ദേഹം പറഞ്ഞു: നഷ്ടപരിഹാരം അടുത്ത ബന്ധുക്കൾക്കാണ് (പിതാവിന്റെ ഭാഗത്ത് കൂടെ), ഭർതാവിന്റെ നഷ്ടപരിഹാര സ്വത്തിൽ നിന്ന് സ്ത്രീ ഒന്നും അനന്തരമെടുക്കുകയില്ല. അപ്പോൾ ളഹാകുബ്നു സുഫ്യാൻ(റ) - മറ്റൊരു നിവേദനത്തിൽ: നബി(സ) അദ്ദേഹത്തെ അഅ്റാബികളുടെ നികുതി പിരിക്കാൻ നിയോഗിച്ചിരുന്നു - ഉമർ(റ)വിനോട് പറഞ്ഞു: സ്ത്രീക്ക് തന്റെ ഭർതാവിന്റെ നഷ്ടപരിഹാര സ്വത്തിൽ നിന്ന് കറുത്ത ഒട്ടകം അനന്തരസ്വത്തായി നൽകണമെന്ന് കൽപിച്ച് കൊണ്ട് റസൂൽ(സ) എനിക്ക് കത്തെഴുതിയിരുന്നു. അങ്ങനെ ഉമർ(റ) തന്റെ അഭിപ്രായത്തിൽ നിന്ന് പിന്തിരിഞ്ഞു. (ദ,തു,ജ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 622, 622, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=9 and h.hadith_no=70), 1, 'وَفِي رِوَايَةٍ: وَكَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اسْتَعْمَلَهُ عَلَى الأَعْرَابِ – كَتَبَ إِلَيَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ أُوَرِّثَ امْرَأَةَ أَشْيَمَ الضِّبَابِيِّ مِنْ دِيَةِ زَوْجِهَا، فَرَجَعَ عُمَرُ. (د,ت,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: നബി(സ) അദ്ദേഹത്തെ അഅ്റാബികളുടെ നികുതി പിരിക്കാൻ നിയോഗിച്ചിരുന്നു - ഉമർ(റ)വിനോട് പറഞ്ഞു: സ്ത്രീക്ക് തന്റെ ഭർതാവിന്റെ നഷ്ടപരിഹാര സ്വത്തിൽ നിന്ന് കറുത്ത ഒട്ടകം അനന്തരസ്വത്തായി നൽകണമെന്ന് കൽപിച്ച് കൊണ്ട് റസൂൽ(സ) എനിക്ക് കത്തെഴുതിയിരുന്നു. അങ്ങനെ ഉമർ(റ) തന്റെ അഭിപ്രായത്തിൽ നിന്ന് പിന്തിരിഞ്ഞു. (ദ,തു,ജ)');
